window.AI_NOTES = {
  "main_1": "Theo quy trình thiết kế vi mạch số dựa trên ASIC/FPGA, quá trình thiết kế thường được chia thành 7 tầng.\nCác tầng này đi từ mô tả yêu cầu, thiết kế/mô phỏng, tổng hợp, bố trí vật lý đến kiểm tra cuối.\nCách chia tầng giúp quản lý thiết kế từ mức ý tưởng đến mạch có thể triển khai.\nFront-End gồm 3 tầng:\n\nTầng mô tả hệ thống: xác định yêu cầu, viết chương trình hệ thống, chương trình mô phỏng và các thông số.\nTầng mô tả RTL/HDL: mô tả mạch bằng Verilog/VHDL, xây dựng module, testbench và mô phỏng chức năng.\nTầng tổng hợp logic: tổng hợp mô tả RTL thành mạch logic/gate-level, xét ràng buộc tốc độ và timing.\n\nBack-End gồm 4 tầng:\n\nTầng ánh xạ công nghệ: chuyển mạch logic sang thư viện cell hoặc tài nguyên FPGA cụ thể.\nTầng bố trí vật lý / placement: sắp xếp vị trí các cell, khối logic hoặc tài nguyên phần cứng.\nTầng nối dây / routing: tạo đường nối giữa các cell, cổng logic hoặc khối chức năng.\nTầng kiểm tra và hoàn thiện: kiểm tra timing, logic, kết quả cuối cùng; sau đó tạo bitstream với FPGA hoặc layout/tape-out với ASIC.",
  "main_3": "Trong quy trình thiết kế vi mạch, phần Back-End thuộc nhiệm vụ của nhà sản xuất/thực hiện vật lý.\nBack-End thường gồm các tầng như: tổng hợp logic, placement, routing, kiểm tra/hoàn thiện layout.\nVì vậy nhiệm vụ Back-End chiếm 4 tầng trong tổng quy trình.",
  "main_9": "Tầng thứ sáu thuộc phần Back-End trong quy trình thiết kế vi mạch.\nSau khi đã bố trí ban đầu và phân tích timing, hệ thống cần xác định lại bố cục cuối cùng để đảm bảo yêu cầu thời gian.\nĐây là bước hoàn thiện vị trí/kết nối vật lý trước khi kiểm tra cuối.\nA là bố cục ban đầu, B là đi dây tự động, còn C nghiêng về bước kiểm tra sau cùng.",
  "main_10": "Tầng thứ bảy là tầng kiểm tra/đánh giá cuối trong quy trình thiết kế.\nNhiệm vụ của tầng này là xác nhận mạch hoạt động đúng về logic sau các bước thiết kế trước đó.\nĐồng thời kiểm tra kết quả cuối cùng trước khi triển khai/chế tạo hoặc nạp xuống FPGA.\nA và D liên quan đến bố cục, B là đi dây tự động, không phải nhiệm vụ tầng cuối.",
  "main_11": "Theo quy trình trong đề, tầng thứ nhất được chia thành 3 công đoạn.\nĐây là tầng đầu của quá trình thiết kế, thường liên quan đến việc xác định yêu cầu và mô tả ban đầu của hệ thống.\nTầng thứ nhất gồm 3 công đoạn:\nViết chương trình hệ thống.\nViết chương trình mô phỏng.\nXác định/khai báo các thông số của hệ thống.",
  "main_12": "Tầng thứ ba là tầng tổng hợp trong quy trình thiết kế.\nNó gồm 3 công đoạn chính: tổng hợp chương trình/mô tả thiết kế, xử lý ràng buộc thời gian liên quan tốc độ xử lý, và xác định/sắp xếp vị trí các ô thành phần.\nVì có đủ 3 phần việc này nên chọn B. 3.\nHiểu ngắn gọn: tầng 3 biến mô tả thiết kế thành cấu trúc phần cứng có xét timing và vị trí",
  "main_14": "Theo dữ liệu của đề, tầng thứ sáu trong quy trình thiết kế gồm 2 công đoạn.\nTầng này thường thuộc phần xử lý cuối của quy trình, sau các bước thiết kế và tổng hợp trước đó.\nTầng thứ sáu gồm 2 công đoạn:\nKiểm tra các hoạt động logic của hệ thống.\nKiểm tra kết quả cuối cùng sau khi thiết kế/tổng hợp.",
  "main_16": "Bước Front-End tập trung vào phần thiết kế mức logic/chức năng trước khi đi vào bố trí vật lý.\nCác công việc gồm: viết chương trình mô tả phần cứng bằng Verilog/VHDL.\nSau đó thực hiện mô phỏng để kiểm tra chức năng thiết kế.\nTiếp theo là tổng hợp để chuyển mô tả HDL thành mạch logic/gate-level.",
  "main_18": "Mạch rời rạc dùng nhiều linh kiện riêng lẻ nên thường tốn diện tích, dây nối nhiều và tốc độ không cao bằng mạch tích hợp.\nNó cũng có thể tiêu tốn điện năng hơn và bị giới hạn khi thiết kế hệ thống lớn, phức tạp.\nVì vậy A và B đều nêu đúng hạn chế của mạch rời rạc.\nC nói “A, B đều sai” nên C sai, do đó chọn D.",
  "main_21": "Bóng bán dẫn được phát minh lần đầu vào năm 1947, nhưng đó chưa phải là mốc sản xuất hàng loạt.\nBóng bán dẫn tiếp giáp sau đó được phát triển và bắt đầu được sản xuất hàng loạt vào khoảng 1951.\nVì câu hỏi hỏi “sản xuất hàng loạt”, không phải “phát minh”, nên chọn 1951.",
  "main_25": "MSI là viết tắt của Medium Scale Integration, tức công nghệ tích hợp quy mô trung bình.\nTrong phân loại mức độ tích hợp IC, MSI thường có số transistor ở mức khoảng hàng trăm đến 1000.\nSo với SSI thì MSI tích hợp nhiều phần tử hơn, nhưng vẫn thấp hơn LSI.\nVì vậy trong các lựa chọn, 1000 là đáp án phù hợp nhất.",
  "main_26": "LSI là viết tắt của Large Scale Integration, tức công nghệ tích hợp quy mô lớn.\nTrong phân loại mức độ tích hợp, LSI thường ứng với số transistor ở mức hàng nghìn đến khoảng 10.000.\nVì vậy trong các lựa chọn đã cho, 10.000 là đáp án phù hợp nhất.",
  "main_29": "IC số thường chia thành hai nền tảng lớn: ASIC và PLDs.\nASIC là vi mạch thiết kế chuyên dụng, tối ưu cho một ứng dụng cụ thể.\nPLDs là nhóm vi mạch logic lập trình được, bao gồm SPLD, CPLD, FPGA.\nA sai vì FPGA chỉ là một loại thuộc PLDs, không ngang cấp với ASIC trong phân loại lớn.",
  "main_36": "FPGA có ưu điểm là không cần chi phí chế tạo chip riêng như ASIC, nên phù hợp với số lượng nhỏ.\nVì không phải đầu tư mặt nạ/quy trình sản xuất riêng, rủi ro tài chính thấp hơn.\nNgười thiết kế có thể nạp lại cấu hình nhiều lần để sửa lỗi hoặc nâng cấp.\nDo đó cả A và B đều là ưu điểm của FPGA.",
  "main_41": "FPGA có ưu điểm là có sẵn, có thể nạp chương trình và kiểm thử nhanh.\nChi phí phát triển ban đầu thấp hơn ASIC vì không cần chế tạo chip riêng.\nFPGA cũng có khả năng cấu hình lại, phù hợp thử nghiệm và phát triển nhanh sản phẩm.\nĐáp án A phù hợp hơn với ASIC khi sản xuất số lượng lớn.",
  "main_42": "FPGA là vi mạch đã được chế tạo sẵn cấu trúc vật lý gồm CLB, LUT, Flip-Flop và mạng nối dây lập trình được.\nNgười thiết kế chỉ cần mô tả mạch bằng HDL rồi công cụ sẽ ánh xạ vào tài nguyên có sẵn, không phải tự thiết kế layout vật lý như ASIC.\nASIC cần thiết kế bố trí vật lý như placement, routing, layout.\nSPLD/CPLD cũng có cấu trúc lập trình được nhưng trong phạm vi đề, đáp án cần chọn là FPGA.",
  "main_45": "CPLD là viết tắt của Complex Programmable Logic Device.\nĐây là thiết bị logic lập trình được có cấu trúc phức tạp hơn SPLD.\nCPLD thường gồm nhiều khối logic kiểu PAL/GAL liên kết với nhau bằng mạng nối dây lập trình được.\nA là SPLD, không phải CPLD.",
  "main_50": "Trong phương pháp SOP (Sum of Products), hàm logic được viết dưới dạng tổng của các tích.\nMỗi tích các biến làm cho ngõ ra bằng 1 được gọi là minterm.\nNói cách khác, minterm ứng với từng tổ hợp đầu vào mà hàm nhận giá trị 1.\nMaxterm dùng trong phương pháp POS, ứng với các tổ hợp làm ngõ ra bằng 0.",
  "main_51": "Trong phương pháp POS (Product of Sums), hàm logic được viết dưới dạng tích của các tổng.\nCác phần tử dạng tổng được xây dựng tại những tổ hợp làm ngõ ra bằng 0 gọi là Maxterms.",
  "main_52": "PAL và GAL là hai loại vi mạch thuộc nhóm SPLD - thiết bị logic lập trình đơn giản.\nChúng có cấu trúc đơn giản, dùng để thực hiện các hàm logic tổ hợp hoặc tuần tự mức nhỏ.\nFPGA không thuộc SPLD mà thuộc nhóm lập trình phức tạp hơn.\nASIC không phải vi mạch lập trình được theo kiểu SPLD.",
  "main_54": "Cấu trúc PLA thường gồm 3 tầng chính.\nTầng 1: Tầng ngõ vào/bộ đệm, tạo tín hiệu vào và tín hiệu đảo của nó.\nTầng 2: Mảng AND lập trình được, dùng để tạo các tích hay product-term.\nTầng 3: Mảng OR lập trình được, dùng để cộng các product-term tạo hàm ngõ ra.",
  "main_57": "Trong FPGA, cấu trúc mảng lập trình được gồm nhiều CLB - Configurable Logic Block.\nCác CLB được liên kết với nhau thông qua hệ thống dây nối lập trình được.\nBên trong CLB thường có LUT, Flip-Flop và mạch chọn để thực hiện hàm logic.\nLUT chỉ là thành phần bên trong CLB, không phải khối liên kết chính của toàn FPGA.",
  "main_60": "Các bộ vi xử lý và bộ nhớ thường yêu cầu tối ưu rất cao về tốc độ, diện tích và công suất.\nVì vậy chúng thường được thiết kế theo cấu trúc Full-Custom ASIC.\nỞ Full-Custom, người thiết kế can thiệp sâu đến mức transistor/layout để đạt hiệu năng tốt nhất.\nSemi-Custom dùng cell có sẵn nên kém tối ưu hơn Full-Custom.",
  "main_61": "Hình vẽ có nhiều khối logic dạng LAB/SPLD được nối với nhau qua PIA — Programmable Interconnect Array.\nĐây là đặc trưng của CPLD, gồm nhiều khối logic đơn giản liên kết bằng mạng nối dây lập trình được.\nFPGA thường có cấu trúc mảng nhiều CLB và I/O block phân bố đều hơn.\nCLB chỉ là khối logic con, không phải nhóm vi mạch tổng thể.",
  "main_62": "Đáp án C đúng vì hình thể hiện cấu trúc tổng quát của FPGA.\nTrong hình có nhiều khối CLB được sắp xếp dạng mảng, xung quanh là các khối I/O block và giữa các CLB là hệ thống programmable interconnect.\nĐây là đặc trưng của FPGA: các khối logic có thể cấu hình được và hệ thống nối dây có thể lập trình.\nSPLD/CPLD không có cấu trúc mảng CLB và liên kết lập trình dạng này.\nD sai vì CLB chỉ là một khối con bên trong FPGA, không phải toàn bộ nhóm vi mạch.",
  "main_63": "Gate Array ASIC được chế tạo sẵn dưới dạng một mảng các tế bào cơ bản giống nhau.\nKhi thiết kế, nhà sản xuất chỉ tùy chỉnh các lớp nối dây để tạo ra mạch mong muốn.\nVì vậy công nghệ này được xem là chỉ dùng một loại tế bào cơ bản.",
  "main_66": "Trong cấu trúc PAL, hàm logic dạng SOP được tạo bằng các tích trước, rồi cộng các tích lại.\nVì vậy cần mảng AND lập trình được để tạo các product-term theo yêu cầu.\nSau đó các product-term được đưa qua mảng OR cố định để tạo ngõ ra.\nC sai vì AND và OR đều lập trình là đặc trưng của PLA, không phải cấu trúc đang hỏi.",
  "main_67": "Trong CPLD, các khối/tế bào logic thường được xây dựng dựa trên cấu trúc kiểu PAL.\nCấu trúc PAL gồm mảng AND lập trình được và mảng OR cố định, phù hợp để tạo các hàm logic.\nFPGA thường dùng LUT, không phải cấu trúc PAL làm tế bào logic chính.\nPLA và PROM là các loại vi mạch khác, không phải thiết bị có tế bào logic kiểu PAL như CPLD.",
  "main_71": "Trong CPLD, tế bào logic thường có cấu trúc phức tạp hơn SPLD, gồm phần logic kiểu PAL và có thể kèm D Flip-Flop để lưu trạng thái.\nHệ thống nối dây bên trong của CPLD thường có khuynh hướng tập trung, giúp thời gian truyền tín hiệu dễ dự đoán hơn.\nCác đáp án B và D sai vì mô tả kiểu nối dây phân tán, linh hoạt, đặc trưng gần với FPGA hơn.",
  "main_76": "Trong FPGA/CPLD, transistor dùng để lập trình nối dây thường hoạt động như một công tắc điều khiển.\nÔ nhớ SRAM lưu bit cấu hình để quyết định transistor đó dẫn hay ngắt.\nMuốn điều khiển transistor dẫn/ngắt thì tín hiệu SRAM phải đưa vào cực G - Gate.\nCực D và S là đường dẫn tín hiệu, không phải chân điều khiển chính.",
  "main_77": "Mạch tổ hợp là mạch có ngõ ra phụ thuộc trực tiếp vào giá trị ngõ vào hiện tại, không cần phần tử nhớ.\nMạch giải mã nhận mã nhị phân ở ngõ vào và tạo tín hiệu ngõ ra tương ứng, nên là mạch tổ hợp.\nFlip-Flop D, mạch đếm 4 bit và thanh ghi dịch đều có phần tử nhớ, hoạt động theo clock nên là mạch tuần tự.",
  "main_79": "Hai ngôn ngữ mô tả phần cứng phổ biến nhất hiện nay là Verilog HDL và VHDL.\nCả hai đều dùng để mô tả, mô phỏng và tổng hợp mạch số.\nVerilog thường có cú pháp gần giống C, còn VHDL có cú pháp chặt chẽ hơn.\nCCS không phải ngôn ngữ mô tả phần cứng phổ biến trong phạm vi câu hỏi này.",
  "main_80": "Theo phạm vi kiến thức của đề, Verilog HDL và VHDL được xem là phát triển vào năm 1983.\nĐây là giai đoạn các ngôn ngữ mô tả phần cứng bắt đầu được xây dựng để mô tả, mô phỏng và thiết kế mạch số.\nCác mốc 1938, 1893, 1839 đều không phù hợp vì quá sớm so với sự phát triển của công nghệ IC và HDL.",
  "main_81": "IEEE 1364 là tiêu chuẩn dùng cho Verilog HDL.\nTrong phạm vi câu hỏi này, đề đang lấy Verilog HDL làm trọng tâm nên đáp án C được xem là đúng.\nCác đáp án ISO, ANSI và IEEE 741 không phải tiêu chuẩn chính của Verilog HDL trong câu hỏi này.",
  "main_82": "Trong Verilog, mạch số có thể được mô tả ở nhiều cấp độ khác nhau.\nMô hình hành vi mô tả mạch theo hoạt động/chức năng.\nRTL mô tả quá trình truyền dữ liệu giữa các thanh ghi và logic xử lý.\nCổng logic mô tả mạch bằng các cổng cơ bản như AND, OR, NOT,...\nVì cả A, B và C đều là cấp độ mô tả trong Verilog nên chọn D.",
  "main_83": "Trong thiết kế bằng Verilog, có hai phương pháp chính là Top-Down và Bottom-Up.\nTop-Down: thiết kế từ hệ thống lớn, sau đó chia nhỏ thành các module con.\nBottom-Up: thiết kế các module nhỏ trước, rồi ghép lại thành hệ thống lớn.\nCả hai phương pháp đều được dùng trong thiết kế và tổng hợp hệ thống số.",
  "main_84": "Trong Verilog, module là khối xây dựng cơ bản để mô tả mạch số.\nMột module có thể là một phần tử riêng lẻ hoặc gồm nhiều module/khối nhỏ hơn bên trong.\nModule cũng giúp kết nối và tổ chức các khối con thành hệ thống cấp cao hơn.\nVì cả A, B và C đều mô tả đúng vai trò của module nên chọn D.",
  "main_86": "Trong Verilog, tên định danh có thể dùng chữ cái hoa, chữ cái thường, chữ số, dấu gạch dưới _ và ký hiệu $.\nTuy nhiên, định danh không được bắt đầu bằng chữ số.\nVí dụ hợp lệ: data_1, clk$test, A_count.\nVì vậy đáp án đầy đủ nhất là A.",
  "main_88": "Trong Verilog, định danh có thể chứa chữ cái, chữ số, dấu _ và ký hiệu $.\nTuy nhiên, định danh không được bắt đầu bằng chữ số.\n5_myproject bắt đầu bằng số 5, nên không hợp lệ.\nCác lựa chọn A, B, D đều bắt đầu bằng chữ cái hoặc _, nên được cho phép.",
  "main_93": "Trong mạch số/Verilog, mức logic thấp được biểu diễn bằng 0.\nMức logic cao được biểu diễn bằng 1.\nX là trạng thái không xác định, còn Z là trạng thái tổng trở cao/thả nổi.\nVì vậy mức logic thấp đại diện bởi 0.",
  "main_94": "Trong mạch số/Verilog, mức logic cao được biểu diễn bằng 1.\nMức logic thấp được biểu diễn bằng 0.\nX là trạng thái không xác định, còn Z là trạng thái trở kháng cao/thả nổi.\nVì vậy mức logic cao đại diện bởi 1.",
  "main_96": "Trong Verilog, trạng thái trở kháng cao hay hở mạch được ký hiệu là Z.\nZ nghĩa là tín hiệu đang bị thả nổi, không được kéo lên 1 hoặc kéo xuống 0.\nTrạng thái này thường gặp ở bus dùng tri-state hoặc net không có driver.\nX là không xác định, còn 0 và 1 là hai mức logic bình thường.",
  "main_97": "Trong Verilog, một hằng số thường được viết theo dạng: <size>'<radix><value>.\nVí dụ: 8'b10101010 nghĩa là số nhị phân 8 bit.\nTrong đó 8 là kích thước, 'b là cơ số nhị phân, 10101010 là giá trị.\nCác đáp án khác sai vì thiếu dấu nháy ' hoặc dùng sai ký hiệu phân cách.",
  "main_106": "Trong Verilog, nếu phần size không được ghi rõ, số bit của hằng số sẽ được xác định ngầm.\nViệc xác định này có thể phụ thuộc vào giá trị cần biểu diễn, quy tắc của mô phỏng, và cách công cụ/máy xử lý số không khai báo size.\nVí dụ thay vì viết 4'b0110, nếu bỏ 4 thì công cụ sẽ tự suy ra độ rộng phù hợp.\nVì vậy theo phạm vi đề, chọn D. Cả 3 trường hợp trên.",
  "main_108": "Trong Verilog, tham số thường được khai báo bằng parameter.\nNó là một hằng số có tên, dùng để đặt giá trị cố định cho module như độ rộng bus, hệ số đếm,...\nSau khi được khai báo hoặc truyền giá trị khi khởi tạo module, tham số không thay đổi trong quá trình mô phỏng/thực thi.\nVì vậy tham số được liên kết với tên định danh không đổi.",
  "main_113": "Trong Verilog/mạch số, đường dây không được kết nối hoặc không có nguồn điều khiển thường ở trạng thái high impedance, ký hiệu là Z.\nZ nghĩa là đường dây đang “thả nổi”, không bị kéo lên 1 hay kéo xuống 0.",
  "main_116": "Trong Verilog, thanh ghi thường được khai báo bằng kiểu dữ liệu reg.\nreg dùng để lưu giá trị trong các khối thủ tục như always hoặc initial.\nVí dụ: reg [7:0] count; mô tả một thanh ghi 8 bit.\nwire là dây nối, tri là dây ba trạng thái, còn bus không phải kiểu dữ liệu chính thức.",
  "main_118": "Trong Verilog, time là kiểu dữ liệu đặc biệt dùng để lưu thời gian mô phỏng.\nNó thường dùng chung với các lệnh hệ thống như $time, $display, $monitor để quan sát thời điểm xảy ra sự kiện.\nwire dùng cho dây tín hiệu, real dùng cho số thực, còn float không phải kiểu dữ liệu chuẩn trong Verilog.\nVì vậy kiểu dùng để đo/lưu thời gian mô phỏng là time.",
  "main_121": "Trong Verilog, mỗi ký tự trong chuỗi thường được lưu bằng 8 bit theo mã ASCII.\nKhai báo reg [8*13:1] string_val; tạo ra tổng cộng 8 × 13 = 104 bit.\nVì mỗi ký tự cần 8 bit nên số ký tự tối đa lưu được là 104 / 8 = 13 ký tự.",
  "main_122": "Chuỗi \"I am overflowed\" có số ký tự nhiều hơn dung lượng mà string_val có thể lưu.\nTrong Verilog, mỗi ký tự cần 8 bit, nên nếu thanh ghi không đủ số bit thì chuỗi bị vượt quá khả năng lưu trữ.\nTrường hợp này gọi là tràn dữ liệu chuỗi.\nA sai vì không thể lưu bình thường nếu độ rộng thanh ghi không đủ.",
  "main_123": "Trong Verilog, toán tử && là toán tử AND logic giữa hai biểu thức/toán hạng.\nNó không AND từng bit, mà xét mỗi toán hạng là đúng hay sai.\nNếu cả hai toán hạng đều khác 0 thì kết quả là 1, ngược lại là 0.\nC sai vì AND từng bit là toán tử &, không phải &&.",
  "main_128": "Trong Verilog, toán tử ^ là toán tử XOR theo từng bit.\nNếu hai toán hạng là nhiều bit, nó sẽ XOR từng cặp bit tương ứng.\nVí dụ: 4'b1010 ^ 4'b1100 = 4'b0110.\nA và B sai vì đó là toán tử AND/OR, còn C sai vì AND từng bit là toán tử &.",
  "main_130": "Trong Verilog, toán tử ~ là toán tử NOT theo bit.\nNó sẽ đảo từng bit của toán hạng: 0 thành 1, 1 thành 0.\nVí dụ: ~4'b1010 = 4'b0101.\nA và C là phép AND, D là phép OR nên không đúng với toán tử ~.",
  "main_131": "Trong Verilog, && là phép AND logic, chỉ xét mỗi toán hạng là đúng hay sai.\nA = 5 là giá trị khác 0 nên được xem là logic 1.\nB = 0 được xem là logic 0.\nVì vậy A && B = 1 && 0 = 0.",
  "main_132": "Trong Verilog, || là phép OR logic, còn ! là phép NOT logic.\nA = 5 là giá trị khác 0 nên được xem là logic 1.\nB = 0 nên !B = 1.\nVì vậy A || !B = 1 || 1 = 1.",
  "main_140": "Trong Verilog, toán tử {} dùng để nối chuỗi bit theo thứ tự từ trái sang phải.\nTa có a = 1'b1, b = 3'b010, c = 3'b101.\nVậy catx = {a, b, c} = 1_010_101, viết gộp lại là 101_0101.",
  "main_141": "Trong Verilog, toán tử {} dùng để nối chuỗi bit theo đúng thứ tự từ trái sang phải.\nTa có b = 3'b010, 2'b11 là 2 bit 11, và a = 1'b1.\nVì vậy caty = {b, 2'b11, a} = 010_11_1.",
  "main_146": "Trong Verilog, phép so sánh quan hệ như < sẽ trả về 1 nếu đúng, 0 nếu sai.\nTuy nhiên nếu một toán hạng có giá trị z hoặc x, kết quả so sánh không thể xác định chắc chắn.\nVì vậy biểu thức 10 < z cho kết quả là X.\nZ là trạng thái tổng trở cao, không phải kết quả hợp lệ của phép so sánh quan hệ.",
  "main_148": "Trong Verilog, === và !== là phép so sánh case equality/case inequality.\nChúng so sánh cả các giá trị đặc biệt như x và z như một giá trị cụ thể.\nVì vậy kết quả trả về chỉ là đúng hoặc sai, tương ứng 1 hoặc 0.\nKhác với == và !=, kết quả có thể bị x nếu toán hạng chứa giá trị không xác định.",
  "main_155": "Biểu thức dùng toán tử điều kiện ?: để chọn ngõ ra Y theo giá trị của sel.\nNếu sel = 00 thì chọn A, sel = 01 chọn B, sel = 10 chọn C, còn lại chọn D.\nNhư vậy có 4 ngõ vào dữ liệu A, B, C, D và 1 ngõ ra Y.\nĐây chính là mạch MUX 4x1.",
  "main_156": "Trong Verilog, x biểu diễn giá trị không xác định.\nKhi một phép tính có toán hạng là x, kết quả thường bị lan truyền trạng thái không xác định.\nVì vậy kết quả thu được được xem là X.\nZ là tổng trở cao, còn U không phải giá trị logic chuẩn trong Verilog.",
  "main_159": "Trong Verilog, toán tử điều kiện ?: có độ ưu tiên rất thấp trong biểu thức.\nNó thường được thực hiện sau các phép toán như logic, so sánh, cộng trừ,...\nVì vậy khi dùng toán tử điều kiện, nên đặt ngoặc để tránh hiểu sai thứ tự thực hiện.\nwhile và for là câu lệnh lặp, không phải toán tử ưu tiên trong biểu thức như ?:.",
  "main_160": "Trong Verilog, câu lệnh gán liên tục dùng từ khóa assign.\nCú pháp đúng là gán giá trị biểu thức <expr> cho tín hiệu <id> bằng dấu =.\nPhần #del là độ trễ tùy chọn nếu muốn mô tả trễ lan truyền.\nB sai vì == là toán tử so sánh, không phải toán tử gán.",
  "main_164": "Trong Verilog, khối always bắt đầu chạy từ thời điểm mô phỏng bắt đầu.\nSau khi thực hiện xong các câu lệnh bên trong, nó sẽ tự động lặp lại liên tục.\nQuá trình này kéo dài cho đến khi mô phỏng kết thúc.\nĐáp án B sai vì mô tả giống khối initial, chỉ chạy một lần rồi dừng.",
  "main_166": "Trong Verilog, always @* tự động tạo danh sách nhạy từ các tín hiệu được dùng bên trong khối lệnh.\nKhối này thường dùng để mô tả mạch tổ hợp.\nKhi có sự thay đổi ở bất kỳ tín hiệu liên quan nào, khối always @* sẽ được thực hiện lại.\nB và C sai vì đó là mô tả mạch tuần tự theo cạnh clock, không phải always @*.",
  "main_170": "Ban đầu clk = 0, sau đó lệnh forever #10 clk = ~clk; làm clock đảo trạng thái sau mỗi 10 đơn vị thời gian.\nMột chu kỳ clock đầy đủ gồm 2 lần đảo: từ 0 → 1 rồi từ 1 → 0.\nVì vậy chu kỳ là 10 + 10 = 20 đơn vị thời gian.\nKhông chọn B vì đề không khai báo timescale, nên chưa thể khẳng định đơn vị là ns.",
  "main_171": "Các lệnh hệ thống như $display, $monitor, $stop, $finish thường được viết trong các khối procedure như initial hoặc always.\nChúng dùng để phục vụ mô phỏng, in kết quả, theo dõi tín hiệu hoặc điều khiển quá trình mô phỏng.\nKhông đặt trực tiếp như một câu lệnh độc lập ngoài procedure trong module.\nVì vậy đáp án đúng là A. Trong quá trình.",
  "main_172": "Trong Verilog, $display(\"..\", arg2, arg3, ..); dùng để in ra màn hình mô phỏng theo chuỗi định dạng đã viết trong dấu \" \".\nCác biến arg2, arg3,... sẽ được chèn vào chuỗi theo các ký hiệu như %b, %d, %h, %s.\nSau khi in xong, $display tự xuống dòng.",
  "main_176": "Khai báo `timescale 10ns/1ns nghĩa là 1 đơn vị thời gian mô phỏng = 10 ns.\nCâu lệnh #5 a = b; sẽ trì hoãn 5 đơn vị thời gian trước khi thực hiện.\nVậy thời gian trì hoãn là 5 × 10 ns = 50 ns.\nPhần 1ns là độ chính xác thời gian, không phải đơn vị tính chính của #5.",
  "main_179": "Một hệ thống số thường được tạo từ nhiều thành phần nhỏ hơn như cổng logic, thanh ghi, bộ đếm, MUX,...\nCác thành phần này được liên kết với nhau bằng dây dẫn/tín hiệu.\nDây dẫn dùng để nối ngõ ra của khối này đến ngõ vào của khối khác.\nVì vậy hệ thống số không chỉ có dây, không chỉ có I/O, mà gồm khối chức năng + kết nối + ngõ vào/ngõ ra.",
  "main_184": "Trong VHDL, entity dùng để mô tả phần giao tiếp bên ngoài của mạch.\nNó khai báo tên mạch và các cổng input/output thông qua phần port.\nCác hoạt động bên trong của mạch được mô tả trong architecture, không phải entity.\nA sai vì process nằm trong architecture; D cũng là vai trò của architecture.",
  "main_186": "Trong Verilog, nếu thanh ghi reg chưa được gán giá trị khởi tạo thì giá trị mặc định là X.\nX biểu diễn trạng thái không xác định.\nĐiều này thường xảy ra ở đầu mô phỏng nếu chưa có initial, reset hoặc phép gán ban đầu.\nZ là tổng trở cao, còn 0 chỉ có khi được gán/reset rõ ràng.",
  "main_188": "Câu lệnh assign là dạng gán liên tục, dùng để mô tả mạch tổ hợp theo kiểu dataflow/hành vi.\nBiểu thức (a|b)&(c|d) mô tả cách tín hiệu đầu vào được xử lý để tạo ra f.\nDù khi tổng hợp có thể tạo ra 2 cổng OR và 1 cổng AND, code không khai báo trực tiếp các cổng đó nên không phải mô tả cấu trúc/netlist mức cổng.",
  "main_192": "Trong phạm vi đề này, $stop được hiểu là lệnh làm dừng/tạm ngắt quá trình mô phỏng tại thời điểm gặp lệnh.\nSau khi $stop, simulator không chạy tiếp ngay mà chờ người dùng thao tác tiếp tục hoặc kiểm tra trạng thái.\nVì vậy đề quy về ý trì hoãn/tạm dừng mô phỏng nên chọn C.",
  "main_195": "Trong Verilog, thang thời gian thường có dạng: `timescale <time_unit>/<time_precision>.\nCác giá trị hợp lệ thường là 1, 10, 100 kèm đơn vị như ns, ps,...\n110ps không phải giá trị chuẩn hợp lệ cho phần độ chính xác thời gian.\nCác đáp án B, C, D đều dùng giá trị hợp lệ như 10ns, 1ps, 100ps.",
  "main_201": "Toán tử === là phép so sánh case equality trong Verilog.\nNó so sánh cả các bit đặc biệt như x và z như những giá trị cụ thể.\nA = 4'b1xxz, B = 4'b1xxx: ba bit đầu giống nhau là 1xx, nhưng bit cuối z khác x.\nVì không giống hoàn toàn từng bit nên A === B trả về 0.",
  "main_204": "Trong Verilog, toán tử ** là phép lũy thừa.\nA = 4'b011 tương đương nhị phân 0011, tức giá trị thập phân 3.\nB = 4'b0011 cũng tương đương giá trị 3.\nVì vậy A ** B = 3 ** 3 = 27.",
  "main_206": "Cổng AND chỉ cho đầu ra bằng 1 khi toàn bộ các đầu vào đều bằng 1.\nVới cổng AND 4 ngõ vào, nếu chỉ cần một ngõ vào bằng 0 thì đầu ra sẽ bằng 0.\nB là đặc trưng gần với cổng OR, không phải AND.\nC và D đều làm đầu ra AND bằng 0.",
  "main_208": "Cổng NOR là cổng OR rồi đảo ngõ ra.\nVới NOR 4 đầu vào, ngõ ra chỉ bằng 1 khi tất cả các đầu vào đều bằng 0.\nNếu chỉ cần một đầu vào bằng 1, cổng OR đã ra 1, sau khi đảo sẽ thành 0.",
  "main_209": "Đoạn code dùng always @(b) và mọi nhánh if/else đều gán giá trị cho a, nên đây là mạch tổ hợp, không tạo latch.\nKhi b = 00 hoặc b = 11 thì a = 0.\nKhi b = 01 hoặc b = 10 thì a = 1.\nĐây đúng với bảng chân trị của cổng XOR giữa hai bit b[1] và b[0].",
  "main_213": "Khối initial đầu tiên gán x = 15, y = 10.\nLệnh repeat(x) lấy giá trị x = 15 để xác định số lần lặp.\nVì vậy $display(\"x=%d\", x); được thực hiện 15 lần.\nKhối while có thể làm thay đổi giá trị x, nhưng trong phạm vi đề, số lần lặp đã được xác định theo x ban đầu là 15.",
  "main_214": "Ban đầu clk = 0.\nCâu lệnh always #5 clk = ~clk; làm clock đảo trạng thái sau mỗi 5 đơn vị thời gian.\nTại thời điểm 5: clk đổi từ 0 → 1, đây là cạnh lên.\nTại 10: 1 → 0 là cạnh xuống; tại 15: 0 → 1 lại là cạnh lên.",
  "main_216": "Trong khối always @(posedge clock), chương trình dùng phép gán blocking =.\nVì vậy các lệnh được thực hiện theo thứ tự từ trên xuống trong cùng một cạnh clock.\nSau data3 = din, các dòng sau lấy ngay giá trị mới của data3, nên data2, data1, data0 đều nhận din.",
  "main_222": "Đáp án D đúng vì chỉ A và C đúng.\nA đúng vì đoạn code tổng hợp thành mạch tổ hợp. Khối always không dùng clock/cạnh clock, và result được gán đầy đủ ở cả nhánh if và else nên không tạo latch hay Flip-Flop.\nC đúng vì khi tổng hợp, result trở thành một đường tín hiệu/ngõ ra được điều khiển bởi logic tổ hợp.\nB sai vì output reg result chỉ là kiểu biến dùng để gán trong always, không có nghĩa chắc chắn tạo phần tử lưu trữ.",
  "main_224": "Hai khối always @(posedge clock) chạy song song khi có cạnh lên clock.\nCả hai đều dùng phép gán chặn =, nên giá trị cập nhật ngay trong khối đang chạy.\nNếu khối a = b chạy trước thì kết quả có thể khác so với khi khối b = a chạy trước.\nVì vậy đoạn code tạo race condition, kết quả không xác định cố định là a=2,b=1 hay a=1,b=2.",
  "main_228": "Verilog được phát triển tại Gateway Design Automation bởi Phil Moorby và nhóm phát triển ban đầu.\nTrong phạm vi đáp án của đề, tên được ghép là Moorby and Thomson, nên chọn D.\nA sai vì chỉ nêu Moorby, chưa đầy đủ theo cách đề yêu cầu.\nB và C không đúng vì không phải cặp người phát triển Verilog.",
  "main_236": "Mạch có ngõ vào I rộng 4 bit và ngõ ra O rộng 2 bit.\nKhi chỉ một bit của I bằng 1, code mã hóa vị trí bit đó thành giá trị nhị phân ở O.\nVí dụ I = 0001 thì O = 00, I = 1000 thì O = 11.\nĐây là đặc trưng của encoder 4 sang 2.",
  "main_239": "Đáp án C đúng vì kết quả là 1011.\nKhi EN=1, chương trình không vào nhánh if (EN == 0) mà xét giá trị của I.\nVới I = 2'b10, câu lệnh tương ứng gán temp = 4'b0100.\nDòng assign O = (HL == 1'b1) ? temp : ~temp; cho biết nếu HL=0 thì ngõ ra sẽ là đảo bit của temp.\nDo đó ~0100 = 1011, nên kết quả là 1011.",
  "main_242": "Đoạn code dùng sel để quyết định đưa tín hiệu I ra vị trí nào trong bus O.\nNếu sel = 00 thì I nằm ở bit thấp nhất, nếu sel = 01, 10, 11 thì I lần lượt được dịch sang các vị trí cao hơn.\nCác bit còn lại được gán 0, nghĩa là chỉ một đường ra nhận dữ liệu tại một thời điểm.\nĐây là đặc trưng của DEMUX: một ngõ vào, nhiều ngõ ra, chọn ngõ ra bằng tín hiệu chọn.",
  "main_243": "Mạch cộng bán phần có 2 ngõ vào là A, B và 2 ngõ ra là S và C.\nTrong code, S = A ^ B chính là bit tổng của phép cộng 1 bit.\nC = A & B chính là bit nhớ/carry khi cả A và B đều bằng 1.\nKhông phải cộng toàn phần vì không có ngõ vào nhớ Cin.",
  "main_246": "Dòng 3 viết: output co, s nhưng thiếu dấu chấm phẩy ; ở cuối câu lệnh.\nTrong Verilog, mỗi khai báo như input, output, wire, assign phải kết thúc bằng ;.\nDòng đúng phải là: output co, s;.\nDòng 2 và 4 hợp lệ về cú pháp.",
  "main_251": "Trong Verilog, từ khóa kết thúc module phải viết đúng là endmodule bằng chữ thường.\nVerilog phân biệt chữ hoa và chữ thường, nên Endmodule không được hiểu là từ khóa hợp lệ.\nDòng 2 và dòng 8 là khai báo input hợp lệ.\nDòng 12 là cách gọi module và nối cổng, không phải lỗi chính trong các lựa chọn.",
  "main_255": "Mạch chốt Latch là mạch nhớ mức, thường hoạt động theo tín hiệu cho phép chứ không cần cạnh clock nên có thể xem là không đồng bộ.\nKhi latch đang được cho phép, đầu ra có thể thay đổi gần như ngay sau khi đầu vào thay đổi.\nSự thay đổi này chỉ bị ảnh hưởng bởi độ trễ lan truyền của cổng logic, thường rất nhỏ.\nVì A, B và C đều đúng nên chọn D.",
  "main_257": "Trong Verilog, có 2 cách nối dây giữa các module khi gọi module con.\nCách 1: nối theo thứ tự cổng (ordered/positional port mapping), ví dụ: DFF D1(clk, d, q);.\nCách 2: nối theo tên cổng (named port mapping), ví dụ: DFF D1(.clk(clk), .D(d), .q(q));.\nNối theo tên cổng rõ ràng hơn và ít bị sai khi thứ tự cổng thay đổi.",
  "main_263": "Trong code, khối always @(posedge clk) cho biết mạch chỉ hoạt động khi có cạnh lên của xung clock, nên đây là mạch Flip-Flop chứ không phải mạch chốt.\nBên trong khối always, lệnh q = D; làm cho ngõ ra q nhận giá trị của ngõ vào D tại thời điểm cạnh lên clock xuất hiện.\nĐây đúng với nguyên lý hoạt động của Flip-Flop D: lưu 1 bit dữ liệu từ ngõ vào D theo xung clock.",
  "main_266": "Mỗi module DFF là một Flip-Flop D, lấy dữ liệu tại cạnh lên của clock C.\nTín hiệu in đi vào FF đầu tiên, sau đó dữ liệu lần lượt truyền qua q[0] → q[1] → q[2] → q[3].\nVì dữ liệu đi vào nối tiếp từng bit qua một đường in, nhưng lấy ra được đủ 4 bit tại q[3:0], nên là vào nối tiếp ra song song.",
  "main_267": "count có độ rộng [3:0] nên đây là mạch đếm 4 bit.\nKhi rst = 1, bộ đếm được reset về 0000.\nKhi sp = 1, mạch mới cho phép đếm; nếu ud = 1 thì count = count + 1, ngược lại count = count - 1.\nVì chiều đếm phụ thuộc tín hiệu điều khiển ud, nên đây là mạch đếm lên/xuống có điều khiển.",
  "main_270": "Khi rst = 1, LED được đặt ban đầu là 8'b1000_0000, tức bit sáng nằm ở vị trí bên trái.\nMỗi cạnh lên của clk, lệnh led = led >> 1 dịch bit 1 sang phải một vị trí.\nKhi LED dịch hết thành 0000_0000, code đặt lại về 1000_0000 để lặp lại.\nVì vậy LED sáng theo kiểu dịch từ trái sang phải.",
  "main_272": "Khi rst = 1, LED bắt đầu ở trạng thái 1000_0000, tức chỉ sáng LED bên trái.\nMỗi xung clock, lệnh (led >> 1) dịch các bit sáng sang phải, rồi cộng 8'b1000_0000 để giữ LED bên trái luôn sáng thêm.\nChuỗi trạng thái sẽ dạng: 1000_0000 → 1100_0000 → 1110_0000 → ... → 1111_1111.\nKhi đạt 1111_1111, code reset về 0000_0000 rồi lặp lại.",
  "main_279": "Trong Verilog, phép gán chặn Blocking = được thực hiện ngay tại dòng lệnh đó.\nLệnh phía sau chỉ chạy sau khi lệnh phía trước đã hoàn thành.\nVì vậy các câu lệnh blocking trong cùng khối always/initial được hiểu là thực hiện tuần tự từ trên xuống.\nKhác với non-blocking <=, các lệnh không được cập nhật đồng thời.",
  "main_280": "Trong Verilog, phép gán không chặn <= thường dùng trong mạch tuần tự như Flip-Flop.\nCác vế phải được đọc tại cùng một thời điểm, sau đó các vế trái mới được cập nhật đồng thời.\nVì vậy nhiều lệnh <= trong cùng khối always không làm thay đổi ngay giá trị cho dòng lệnh kế tiếp.\nĐây là lý do <= phù hợp để mô tả các FF hoạt động song song theo cạnh clock.",
  "main_284": "Mạch tuần tự đồng bộ thường gồm 3 khối chính: khối logic tổ hợp, khối nhớ và khối điều khiển xung clock.\nKhối logic tổ hợp dùng để tạo trạng thái kế tiếp và ngõ ra.\nKhối nhớ thường là các Flip-Flop, dùng để lưu trạng thái hiện tại.\nXung clock giúp các trạng thái thay đổi đồng bộ theo cùng một thời điểm.",
  "main_285": "Mạch tuần tự đồng bộ thường gồm 3 khối chính: thanh ghi trạng thái, logic trạng thái kế tiếp và logic ngõ ra.\nThanh ghi trạng thái lưu trạng thái hiện tại bằng các Flip-Flop.\nLogic trạng thái kế tiếp tính trạng thái mới dựa trên ngõ vào và trạng thái hiện tại.\nLogic ngõ ra tạo tín hiệu đầu ra của mạch.",
  "main_286": "Thanh ghi trạng thái dùng để lưu trạng thái hiện tại của mạch tuần tự.\nNó thường gồm nhiều Flip-Flop D cùng được điều khiển bởi một xung clock chung.",
  "main_287": "Trong mạch tuần tự đồng bộ, trạng thái kế tiếp được tạo bởi mạch logic tổ hợp.\nMạch này dựa vào ngõ vào bên ngoài và trạng thái hiện tại đang lưu trong thanh ghi.\nTừ đó nó tính ra trạng thái mới để đưa vào các Flip-Flop ở cạnh clock tiếp theo.\nA chỉ mô tả khối nhớ, C chỉ mô tả logic tạo ngõ ra, không phải logic trạng thái kế tiếp.",
  "main_288": "Trong mạch tuần tự đồng bộ, mạch logic ngõ ra có nhiệm vụ tạo tín hiệu đầu ra của hệ thống.\nNó thường là mạch tổ hợp, nhận thông tin từ trạng thái hiện tại và/hoặc ngõ vào để tạo ngõ ra.\nA là thanh ghi trạng thái, không phải logic ngõ ra.\nB là mạch logic trạng thái kế tiếp, không phải mạch tạo ngõ ra.",
  "main_292": "Đáp án A đúng vì máy trạng thái Mealy có ngõ ra phụ thuộc vào trạng thái hiện tại và tín hiệu đầu vào hiện tại.\nCó thể viết: Output = f(Current State, Input).\nVì phụ thuộc vào input nên ngõ ra của Mealy có thể thay đổi ngay khi input thay đổi, không cần chờ chuyển sang trạng thái mới.\nB mô tả gần với máy Moore, vì máy Moore có ngõ ra phụ thuộc chủ yếu vào trạng thái hiện tại.",
  "main_294": "Trong mạch chia tần số kiểu đếm rồi đảo trạng thái ngõ ra, mỗi lần đếm đủ K xung vào thì ngõ ra đổi trạng thái một lần.\nMột chu kỳ đầy đủ của ngõ ra cần 2 lần đổi trạng thái, nên cần tổng cộng 2K xung vào.\nDo đó tần số ngõ ra là: B = A / (2K).\nSuy ra K = A / (2B).",
  "main_295": "Clock vào là 50 MHz, tức có 50.000.000 xung/giây.\nTrong code, clkout đảo trạng thái mỗi khi count = 25.000.000, tức sau 0,5 giây.\nMột chu kỳ đầy đủ của clkout cần 2 lần đảo trạng thái.\nVậy chu kỳ ngõ ra là 1 giây, suy ra tần số là 1 Hz.",
  "main_298": "Khi speed = 1, code dùng nhánh đếm đến 12.500.000 rồi đảo trạng thái clkout.\nClock vào là 50 MHz, tức 50.000.000 xung/giây.\nMỗi lần đảo clkout mất 12.500.000 / 50.000.000 = 0,25 s.\nMột chu kỳ đầy đủ cần 2 lần đảo, nên chu kỳ là 0,5 s, tương ứng 2 Hz.",
  "main_300": "Trong module DEM_8BIT, tín hiệu OUT được gán giá trị bên trong khối always.\nVới Verilog, tín hiệu được gán trong always phải khai báo kiểu reg.\nNhưng code lại khai báo: output [7:0] OUT; nên bị lỗi kiểu biến.\nCần sửa thành: output reg [7:0] OUT;",
  "main_301": "rst = 0 chỉ cho biết bộ đếm không bị reset, nên có thể tiếp tục đếm nếu ss = 1.\nTuy nhiên xung nhịp đếm thực tế của DEM_8BIT là clk_1_2Hz lấy từ module CK_DIV.\nTần số clk_1_2Hz phụ thuộc vào tín hiệu SPEED: SPEED=0 thì 1 Hz, SPEED=1 thì 2 Hz.\nĐề chỉ cho rst = 0 mà không cho SPEED, nên chưa xác định được xung nhịp đếm.",
  "main_303": "Module tổng thể là DEM_8BIT_2SPEED.\nTrong phần khai báo cổng, module này chỉ có một ngõ ra là LED_8out.\nLED_8out có dạng [7:0], tức là một bus 8 bit, nhưng vẫn được tính là một ngõ ra hoàn chỉnh.\nTín hiệu clk_1_2Hz chỉ là dây nội bộ, không phải ngõ ra của module tổng thể.",
  "final2024_2": "Trong Verilog, if và case là câu lệnh tuần tự/procedural statement.\nVì vậy chúng thường được đặt trong các khối procedure như always hoặc initial.\nBên ngoài procedure chỉ dùng các lệnh dạng song song như assign, khai báo module, wire, reg,...\nKhông dùng assign bên trong if/case procedural; trong đó thường dùng = hoặc <=.\nBạn chưa cung cấp đáp án đã chọn nên chưa thể đánh giá đúng/sai lựa chọn của bạn.",
  "final2024_7": "Trong Verilog, số nhị phân được viết theo dạng: <số_bit>'b<giá_trị>.\nGiá trị thập phân 6 đổi sang nhị phân là 0110 nếu biểu diễn bằng 4 bit.\nVì vậy cách viết đúng trong Verilog là 4'b0110.\nCác dạng 0b0110, 0110b, 110b không phải cú pháp chuẩn của Verilog.",
  "final2024_9": "Trong Verilog, toán tử == là phép so sánh logic thông thường.\nNếu toán hạng có chứa x hoặc z, kết quả so sánh có thể trở thành x vì không xác định chắc đúng hay sai.\nBiểu thức 4'b1z0x == 4'b1z0x nhìn giống nhau, nhưng == không so sánh chắc chắn được các bit x, z.\nMuốn so sánh cả x, z như giá trị cụ thể thì phải dùng ===.",
  "final2024_14": "Trong Verilog, phép gán không chặn <= sẽ đọc giá trị vế phải trước, rồi cập nhật vế trái sau.\nBan đầu a = 0, b = 1.\nLệnh a <= 1 làm a được cập nhật thành 1 sau khi khối kết thúc.\nLệnh b <= a lấy giá trị a cũ = 0, nên b trở thành 0.",
  "final2024_21": "Trong Verilog, biến kiểu reg được phép gán giá trị bên trong khối thủ tục như always.\nĐoạn B có reg a,b; always @* begin a <= 1; b <= 1; end nên hợp lệ về mặt mô tả.",
  "final2024_25": "Trong Verilog, tên định danh có thể chứa chữ cái, chữ số, dấu _ và ký hiệu $.\nTuy nhiên, tên định danh không được bắt đầu bằng chữ số.\n4my_identifier bắt đầu bằng số 4 nên là cách đặt tên sai.\nCác tên còn lại bắt đầu bằng chữ cái hoặc _, nên hợp lệ trong Verilog.",
  "final2024_26": "Quy trình thiết kế vi mạch số thường bắt đầu bằng HDL coding, tức viết mô tả mạch bằng Verilog/VHDL.\nSau đó simulation để kiểm tra chức năng trước khi tổng hợp.\nTiếp theo là synthesis, chuyển HDL thành mạch logic/gate-level.\nSau tổng hợp mới đến placement and routing, rồi cuối cùng timing analysis and verification để kiểm tra timing và xác nhận thiết kế.",
  "final2024_28": "Trong Verilog, bus/vector tín hiệu được khai báo bằng cách đặt độ rộng bit trước tên tín hiệu.\nwire [3:0] BusC; nghĩa là BusC là bus 4 bit gồm các bit từ BusC[3] đến BusC[0].\nA và C giống khai báo mảng wire, không phải bus vector kiểu thông dụng; B sai vì [4] không phải cú pháp khai báo bus đúng.",
  "final2024_30": "Khối đồng bộ phải cập nhật trạng thái tại cạnh lên của clock, nên dùng always @(posedge Clk).\nstate_reg là thanh ghi trạng thái, nhận giá trị kế tiếp từ state_next sau mỗi xung clock.\nTrong mạch tuần tự đồng bộ, nên dùng phép gán không chặn <= để các FF cập nhật đồng thời.\nA là gán liên tục nên không tạo FF; B dùng = không chuẩn cho mạch tuần tự.",
  "exam01_3": "Trong Verilog, giá trị Z biểu diễn trạng thái high impedance hay tổng trở cao.\nTrạng thái này thường xuất hiện khi đường tín hiệu bị thả nổi hoặc không được điều khiển.\nX mới là giá trị chưa biết/không xác định.\nGiá trị chưa khởi tạo thường có thể xuất hiện dưới dạng X, không phải Z.",
  "exam01_4": "Trong Verilog, giá trị thập phân có thể viết trực tiếp như 15, đây là số thập phân không khai báo kích thước.\nCũng có thể viết dạng có kích thước và cơ số như 8'd15, nghĩa là số thập phân 15 biểu diễn bằng 8 bit.\n4'd15 cũng hợp lệ vì 15 biểu diễn vừa đủ trong 4 bit là 1111.\nVì cả 8'd15, 15, và 4'd15 đều là cách biểu diễn giá trị thập phân hợp lệ nên chọn D.",
  "exam01_7": "Trong Verilog, wire là kiểu dây nối, không được gán trực tiếp bằng các câu lệnh như A = 1;.\nMuốn gán cho wire phải dùng câu lệnh gán liên tục assign, ví dụ assign A = 1'b1;.\nNgoài ra các câu lệnh gán tuần tự như trên phải đặt trong initial hoặc always và thường dùng với kiểu reg.\nVì đoạn code sai cách mô tả nên không thể xác định hợp lệ giá trị cuối của B.",
  "exam01_8": "Đây là cách khai báo bus tín hiệu 8 bit trong Verilog với kiểu wire.\nCú pháp đúng đặt độ rộng bus trước tên tín hiệu: [7:0] signal_a.\nB là dạng mảng wire, không phải cách biểu diễn bus tín hiệu theo đề.\nC tuy cũng là vector 8 bit nhưng là kiểu reg, còn câu hỏi đang hỏi bus tín hiệu kiểu dây wire.",
  "exam01_10": "Bộ nhớ 1024 byte nghĩa là có 1024 ô nhớ, mỗi ô rộng 8 bit.\nTrong Verilog, reg [7:0] mem [1023:0] mô tả mảng gồm 1024 phần tử, mỗi phần tử là 8 bit.\nBạn chọn B. reg [1024] mem là sai vì đây chỉ là một thanh ghi/vector rộng khoảng 1025 bit, không phải bộ nhớ gồm 1024 byte.\nC sai vì mô tả 8 phần tử, mỗi phần tử rộng 1024 bit, bị đảo cấu trúc bộ nhớ.",
  "exam01_16": "Trong Verilog, #20 nghĩa là trì hoãn 20 đơn vị thời gian mô phỏng.\nĐơn vị cụ thể là ns, us hay ms phụ thuộc vào khai báo `timescale của chương trình.\nVí dụ nếu `timescale 1ns/1ps thì #20 là 20 ns.\nNếu không có timescale, ta chưa xác định được đơn vị thời gian cụ thể.",
  "exam01_18": "Trong Verilog, câu lệnh assign là phép gán liên tục dùng để mô tả mạch tổ hợp.\nVế trái của assign phải là kiểu net, thường dùng nhất là wire.\nKiểu reg thường được gán bên trong khối always hoặc initial, không dùng trực tiếp với assign trong Verilog chuẩn.\nVì vậy r_reg trong assign r_reg = 4'b0101; nên khai báo là wire.",
  "exam01_20": "Trong mạch tuần tự đồng bộ, Flip-Flop D thường được dùng để lưu và đồng bộ dữ liệu theo xung clock.\nTại cạnh kích hoạt của clock, ngõ ra Q nhận giá trị từ ngõ vào D.\nVì chỉ có một ngõ dữ liệu D nên FF D dễ dùng để thiết kế thanh ghi, bộ đếm, FSM.\nFF JK, RS, T cũng là phần tử nhớ nhưng không thuận tiện bằng FF D trong thiết kế đồng bộ.",
  "exam01_21": "Dịch phải 2 bit nghĩa là bỏ 2 bit thấp nhất a[1:0], các bit còn lại a[7:2] dịch xuống phải.\nHai bit cao mới được chèn thêm 00, nên kết quả là {2'b00, a[7:2]}.\nBạn chọn C là sai vì cú pháp không hợp lệ: dùng () thay vì {} và viết sai chỉ số a[7;2].\nD chỉ là biểu thức dịch phải, chưa gán lại vào a, nên không phải câu lệnh lưu kết quả vào thanh ghi.",
  "exam01_24": "Vì o được khai báo là output reg, nên phải gán trong khối thủ tục như always.\nPhương án A dùng always @(i,s) và chọn ngõ ra theo tín hiệu chọn s.\nNếu s = 1 thì o = i[1], nếu s = 0 thì o = i[0], đúng chức năng MUX 2 sang 1.\nB sai vì viết sai từ khóa assign thành asign.\nC sai vì dùng assign cho biến kiểu reg; D sai vì câu lệnh gán không nằm trong always/initial.",
  "exam01_25": "Mạch DEMUX 1 sang 2 dùng tín hiệu chọn s để đưa ngõ vào i ra một trong hai ngõ ra o[0] hoặc o[1].\nPhương án B dùng if (s) ... else ... nên gần đúng với cách điều khiển chọn ngõ ra của DEMUX.\nA sai vì i chỉ là 1 bit nhưng lại dùng i[0], i[1].\nC sai cú pháp và gán trùng o[0].",
  "exam01_31": "Reset đồng bộ nghĩa là reset chỉ được kiểm tra tại cạnh clock, nên danh sách nhạy chỉ nên có posedge clk.\nMô tả đúng phải là: always @(posedge clk) if (reset) q <= 0; else q <= q + 1;\nA và B đưa reset vào sensitivity list nên là reset bất đồng bộ/không đúng chuẩn reset đồng bộ.\nC và D còn sai cú pháp vì thiếu ký hiệu @ sau always.\nVì vậy không có lựa chọn nào đúng hoàn toàn.",
  "online1_1": "Ngõ ra tri-state có 3 trạng thái: 0, 1 và Z.\nTrạng thái thứ ba Z là trạng thái tổng trở cao, nghĩa là ngõ ra gần như bị cách ly điện khỏi mạch.\nKhi đó tín hiệu không kéo lên 1 cũng không kéo xuống 0.\nA sai vì đây không phải hệ logic tam phân; D sai vì không phải mức điện áp nằm giữa 0 và 1.",
  "online1_2": "Với số bù 2 8-bit, miền giá trị biểu diễn được là từ -2⁷ đến 2⁷ - 1.\nTức là từ -128 đến +127.\nDo đó số âm nhỏ nhất biểu diễn được là -128.\nA và B sai vì vượt ngoài phạm vi 8-bit bù 2, D sai vì chưa phải giá trị âm nhỏ nhất.",
  "online1_7": "Cổng NOR là cổng OR có đảo ngõ ra.\nCổng OR chỉ bằng 0 khi tất cả input đều bằng 0.\nSau khi đảo, NOR sẽ cho ngõ ra bằng 1 trong trường hợp đó.\nNếu chỉ cần một input bằng 1 thì OR = 1, nên NOR = 0.",
  "online1_8": "Câu lệnh assign là gán liên tục, thường dùng để mô tả mạch tổ hợp theo kiểu dataflow.\nBiểu thức (a | b) & (c | d) cho biết dữ liệu từ các tín hiệu a, b, c, d được xử lý để tạo ra f.",
  "online1_10": "Trong Verilog, phép cộng + là phép toán số học.\nNếu trong toán hạng có bit x thì giá trị toán hạng không xác định hoàn toàn.\nVới A = 4'b001x, không biết bit cuối là 0 hay 1 nên kết quả cộng với B = 4'b1011 không xác định chắc chắn.\nDo đó phép cộng trả về toàn bộ kết quả dạng xxxx.",
  "online1_11": "Trong Verilog, các mức logic cơ bản được hỗ trợ là 0, 1, X, Z.\nX biểu diễn giá trị không xác định, còn Z biểu diễn trạng thái tổng trở cao.\nU không phải là mức logic chuẩn trong Verilog.\nU thường gặp trong VHDL, dùng để chỉ giá trị chưa khởi tạo.",
  "online1_12": "Trong Verilog, toán tử ** là toán tử lũy thừa.\nA = 4'b011 được hiểu là giá trị nhị phân 0011, tức là 3.\nB = 4'b0011 cũng có giá trị là 3.\nVì vậy A ** B = 3 ** 3 = 27.",
  "online1_18": "Trong Verilog, timescale có dạng: `timescale <time_unit>/<time_precision>.\nCác giá trị hợp lệ thường là 1, 10, 100 nhân với đơn vị như s, ms, us, ns, ps, fs.\n110ps không phải giá trị chuẩn hợp lệ cho time precision.\nCác lựa chọn B, C, D đều dùng giá trị hợp lệ như 10ns, 1ps, 100ps.",
  "online1_19": "Với A = 8'b00111001, lấy A[5:3] ta được 3 bit là 111.\nB = ~|A là phép NOR rút gọn: vì trong A có bit 1 nên |A = 1, do đó B = 0.\n3{B} nghĩa là lặp B 3 lần, nên được 000.\nVì vậy {A[5:3], 3{B}} = {111, 000} = 6'b111000.",
  "online2_2": "Với blocking assignment =, các lệnh chạy tuần tự từ trên xuống.\nBan đầu a = 1, b = 2; lệnh a = b; làm a nhận giá trị 2.\nNgay sau đó, lệnh b = a; lấy giá trị mới của a, nên b cũng bằng 2.\nKết quả cuối là a = 2, b = 2, nhưng không có lựa chọn nào ghi vậy.",
  "online2_6": "Trong Verilog, các lệnh delay # trong cùng khối initial được tính nối tiếp nhau.\nLệnh 1 #5 x = 1'b0; thực thi tại thời điểm 5.\nSau đó mới bắt đầu tính tiếp #15 cho statement 2.\nVì vậy statement 2 y = 1'b1 thực thi tại thời điểm 5 + 15 = 20.",
  "online2_11": "Trong Verilog, khai báo timescale có dạng: `timescale <time_unit>/<time_precision>.\nGiá trị thời gian hợp lệ thường chỉ được dùng theo các mức 1, 10, 100 với đơn vị s, ms, us, ns, ps, fs.\n110ps không phải giá trị chuẩn hợp lệ cho phần time precision.\nCác đáp án B, C, D đều dùng giá trị hợp lệ như 10ns, 100ns, 1ns, 1ps, 100ps.",
  "online2_19": "Module xét 2 bit của b: nếu b = 00 hoặc b = 11 thì a = 0.\nNếu b = 01 hoặc b = 10 thì a = 1.\nĐây chính là bảng chân trị của cổng XOR giữa b[1] và b[0].\nKhông tạo latch vì mọi nhánh if/else đều gán giá trị cho a.",
  "online2_20": "Trong Verilog, net như wire cần có nguồn điều khiển, gọi là driver.\nNếu một net không có driver nào điều khiển, nó sẽ ở trạng thái high impedance, ký hiệu là Z.\nZ nghĩa là đường dây bị thả nổi, không bị kéo lên 1 hay kéo xuống 0.\nX là không xác định, còn U không phải giá trị logic chuẩn của Verilog.",
  "online2_22": "Trong Verilog, biến kiểu reg nếu chưa được gán giá trị ban đầu thì mặc định là X.\nX biểu diễn trạng thái không xác định.\nTrạng thái này thường xuất hiện ở đầu mô phỏng nếu chưa có initial, reset hoặc phép gán.\nZ là tổng trở cao, 0 chỉ có khi được gán rõ ràng, còn U không phải mức logic chuẩn của Verilog.",
  "exam01_1": "Đáp án D đúng vì các khối logic chính trong FPGA thường dùng LUT để hiện thực hàm logic.\nLUT lưu bảng chân trị của hàm, nên có thể cấu hình lại theo thiết kế.\nMạng AND/OR là cách mô tả gần với PAL/PLA hơn, không phải cấu trúc logic chính của FPGA.",
  "exam01_2": "Đáp án D là đáp án theo dữ liệu đề vì chọn cả SPLD, CPLD và LUT.\nTuy nhiên về bản chất, FPGA hiện thực hàm chức năng chủ yếu bằng LUT trong các CLB.\nSPLD và CPLD là các họ PLD khác, không phải mô hình cấu hình bên trong FPGA.\nCần kiểm tra lại đáp án.",
  "exam01_5": "Đáp án B đúng vì hằng 4'bz1 có độ rộng 4 bit nhưng chỉ ghi 2 ký tự z1.\nKhi bit cao nhất được ghi là z, phần mở rộng bên trái cũng được điền bằng z.\nVì vậy giá trị tương đương là 4'bzzz1.",
  "exam01_6": "Đáp án A đúng vì 8'b11 là hằng nhị phân có độ rộng 8 bit.\nGiá trị 11 chỉ chiếm 2 bit thấp, nên các bit còn thiếu bên trái được thêm 0.\nDo đó biểu diễn đầy đủ là 8'b00000011.",
  "exam01_9": "Đáp án C đúng vì reg a [3:0]; khai báo một mảng gồm 4 phần tử, mỗi phần tử là reg 1 bit.\nreg [3:0] a; là một vector 4 bit, không phải mảng 4 phần tử.\nCâu hỏi đang hỏi mảng, nên cần dùng cú pháp có chỉ số mảng sau tên biến.",
  "exam01_11": "Đáp án A hợp lệ về cú pháp vì wire có thể được điều khiển bằng các câu lệnh assign liên tục.\nCác phương án dùng reg với assign liên tục hoặc gán trực tiếp ngoài procedural block đều không đúng cách.\nLưu ý A có nhiều driver cho a nên khi mô phỏng có thể gây xung đột giá trị; câu này chủ yếu xét tính hợp lệ cú pháp.\nCần kiểm tra lại đáp án nếu đề xét ngữ nghĩa nhiều driver.",
  "exam01_12": "Đáp án C không hợp lệ vì a được khai báo [3:0] nhưng lại chọn part-select a[0:3] ngược chiều khai báo.\nTrong Verilog part-select thông thường phải dùng cùng chiều với range đã khai báo, tức a[3:0].\nA và B đều gán toàn bộ vector 4 bit hợp lệ.",
  "exam01_13": "Đáp án C đúng vì bên trong một khối always, các câu lệnh procedural được thực hiện tuần tự theo thứ tự viết.\nA sai vì các khối always khác nhau trong Verilog chạy song song với nhau, không chạy tuần tự.\nB sai vì các câu lệnh bên trong cùng một khối always không xử lý đồng thời, mà xử lý tuần tự, đặc biệt khi dùng phép gán blocking =.\nD sai vì wire/net không được gán trực tiếp trong khối always; nếu muốn gán trong always thì thường dùng reg/logic.",
  "exam01_14": "Đáp án A đúng vì if và case là câu lệnh procedural trong Verilog.\nChúng phải đặt bên trong always, initial, task hoặc function.\nNgoài procedural block chỉ dùng được continuous assign, instance module hoặc generate phù hợp.",
  "exam01_15": "Đáp án C đúng vì cú pháp bắt sự kiện cạnh lên là always @(posedge clk).\nKý hiệu @ dùng để khai báo sensitivity/event control cho khối always.\nnegedge là cạnh xuống, còn thiếu @ thì không đúng cú pháp always chuẩn.",
  "exam01_17": "Đáp án C đúng vì <= là phép gán không chặn trong Verilog.\nTrong cùng một bước thời gian, vế phải được lấy mẫu trước rồi các vế trái cập nhật đồng thời.\nDo đó a<=1 và b<=0 mô tả cập nhật song song, thường dùng cho mạch tuần tự.",
  "exam01_19": "Đáp án A đúng vì a được gán bên trong khối always.\nTín hiệu nhận gán procedural trong Verilog phải khai báo kiểu reg.\nwire chỉ dùng cho gán liên tục bằng assign hoặc kết nối module/cổng.",
  "exam01_22": "Đáp án C đúng vì c phải rộng 16 bit.\nTrong Verilog: reg [3:0] a, b; c = {a, a, b, a};\na rộng 4 bit, b rộng 4 bit. Phép nối {a, a, b, a} gồm 4 phần, mỗi phần rộng 4 bit.\nTổng độ rộng là 4 + 4 + 4 + 4 = 16 bit.\nVì vậy c cần khai báo dạng reg [15:0] c để chứa đủ kết quả nối. Đáp án 4 bit hoặc 8 bit đều không đủ.",
  "exam01_23": "Đáp án C đúng vì output o là wire nên phải gán bằng assign liên tục.\nToán tử điều kiện s ? i[0] : i[1] mô tả MUX 2:1: s quyết định chọn một trong hai ngõ vào.\nCác phương án gán trực tiếp hoặc dùng if ngoài always không hợp lệ với wire.",
  "exam01_26": "Đáp án B đúng vì đề gốc khai báo ngõ ra o là output reg [1:0].\nVới kiểu reg, o được phép gán trong khối procedural always.\nKhối always @(i, s) mô tả logic tổ hợp phụ thuộc vào tín hiệu i và s.\nTùy theo giá trị của s, tín hiệu i được đưa ra một trong hai nhánh o[0] hoặc o[1].\nC sai trong ngữ cảnh đề gốc vì assign phù hợp với output wire/net, còn đề đang khai báo output reg.",
  "exam01_27": "Đáp án D đúng vì Verilog hỗ trợ primitive gate theo dạng and(out, in1, in2, in3).\nỞ đây and(D,A,B,C) tạo cổng AND 3 ngõ vào và đưa kết quả ra D.\nassign and(...) sai cú pháp, còn từ khóa and không dùng như toán tử chữ trong biểu thức.",
  "exam01_28": "Đáp án B đúng vì D Flip-Flop lấy mẫu D tại cạnh lên clock với always @(posedge clk).\nQ là output reg nên có thể được gán trong always.\nTrong thiết kế tuần tự nên ưu tiên <=, nhưng đáp án B vẫn đúng về dạng mô tả FF theo đề.",
  "exam01_29": "Đáp án C đúng vì cú pháp khởi tạo module trong Verilog là: TênModule tên_instance(.port(signal), ...).\nTên cổng phải khớp đúng chữ hoa/thường với module gốc, nên .clk khác .Clk nếu module khai báo clk.\nPort map là cú pháp VHDL, không phải Verilog.",
  "exam01_30": "Đáp án C đúng vì {Di, r_reg[7:1]} đưa bit nối tiếp Di vào bit cao nhất.\nCác bit cũ r_reg[7:1] được dịch sang phải một vị trí.\nDùng | hoặc + với Di không tạo đúng cấu trúc thanh ghi dịch.",
  "online1_3": "Đáp án B đúng vì $stop dùng để tạm dừng mô phỏng.\nKhi gặp $stop, simulator dừng lại để người dùng kiểm tra trạng thái hoặc tiếp tục chạy.\nMuốn kết thúc mô phỏng thường dùng $finish.",
  "online1_4": "Đáp án C đúng vì: Có.\nMạch tổ hợp thuần phải nhạy với mọi tín hiệu đầu vào ảnh hưởng đến ngõ ra.\nNếu thiếu input trong sensitivity list, mô phỏng có thể không cập nhật đúng và dễ suy ra latch ngoài ý muốn.",
  "online1_5": "Đáp án B đúng vì số nhị phân không dấu 8 bit có 2^8 giá trị khác nhau.\nDải giá trị là từ 0 đến 2^8 - 1.\nVì vậy giá trị lớn nhất là 255, không phải 256 vì 256 cần 9 bit để biểu diễn.",
  "online1_6": "Các đáp án B, C đúng vì: B: Chi phí thiết kế thấp hơn; C: Linh hoạt hơn.\nFPGA có chi phí phát triển ban đầu thấp và có thể cấu hình lại nên linh hoạt hơn ASIC.\nTuy nhiên FPGA thường không nhanh và tối ưu bằng ASIC khi sản xuất số lượng lớn.",
  "online1_9": "Đáp án D đúng vì cổng AND chỉ cho ngõ ra bằng 1 khi tất cả 4 ngõ vào đều bằng 1.\nNếu chỉ cần một ngõ vào bằng 0 thì ngõ ra của cổng AND sẽ bằng 0.\nA sai vì “ít nhất một input bằng 1” là chưa đủ để AND ra 1.\nB và C sai vì có input bằng 0 thì ngõ ra AND không thể bằng 1.",
  "online1_13": "Đáp án D đúng vì các delay trong một initial block là delay tương đối nối tiếp nhau.\nCâu lệnh 1 chạy sau #5, rồi câu lệnh 2 chạy thêm #15 nữa.\nVì vậy thời điểm của statement 2 là 5 + 15 = 20.",
  "online1_14": "Đáp án A đúng vì FPGA có thể nạp cấu hình trực tiếp sau khi tổng hợp và place-route.\nKhông cần chế tạo mask/chip riêng như ASIC, standard cell hay full-custom.\nDo đó thời gian quay vòng thiết kế và kiểm thử thường ngắn nhất.",
  "online1_15": "Đáp án C đúng vì: X.\nTrong mô phỏng Verilog, biến reg chưa khởi tạo có giá trị X.\nX biểu thị trạng thái chưa xác định, không phải 0, 1 hay Z.",
  "online1_16": "Đáp án A đúng vì: Số hex 32 bit.\nHằng hex không ghi độ rộng được xem là hằng không định cỡ.\nTheo phạm vi đề, hằng không định cỡ thường được lấy theo độ rộng mặc định 32 bit.",
  "online1_17": "Đáp án B đúng vì: Z.\nNet không có nguồn điều khiển sẽ ở trạng thái trở kháng cao Z.\nZ biểu thị đường dây bị thả nổi, không bị kéo lên 1 hoặc kéo xuống 0.",
  "online1_20": "Đáp án C đúng vì: Tạo mạch từ đặc tả đã cho.\nSynthesis là quá trình chuyển đặc tả/mô tả HDL thành cấu trúc mạch phần cứng.\nNó khác với mô phỏng, vì mô phỏng chỉ kiểm tra hành vi còn tổng hợp tạo netlist logic.",
  "online1_21": "Đáp án D đúng vì ^A là reduction XOR của A=10011, có 3 bit 1 nên C=1.\nA[3:1] = 001, {2{C}} = 11 và B[2:0] = 110.\nNối lại được 00111110.",
  "online1_22": "Đáp án C đúng vì ~B với B=1xxx sẽ có bit MSB bằng 0.\nA có bit MSB bằng 1, nên A == ~B chắc chắn sai ngay ở bit cao nhất.\nVì có một bit xác định khác nhau nên kết quả so sánh là 0, không phải X.",
  "online2_1": "Đáp án D đúng vì toán tử ** là lũy thừa.\nA=4'b011 tương đương 3 và B=4'b0011 cũng tương đương 3.\nDo đó A**B = 3^3 = 27.",
  "online2_3": "Đáp án B đúng vì 'h1234 là hằng thập lục phân không khai báo độ rộng.\nTrong Verilog, hằng số không khai báo size thường được xử lý theo độ rộng mặc định tối thiểu/word, thường là 32 bit theo đề.\nMỗi chữ số hex có 4 bit, nhưng do không ghi size nên đề chọn 32 bit.",
  "online2_4": "Đáp án C đúng vì cả data0, data1, data2, data3 đều nhận trực tiếp din tại cùng cạnh lên clock.\nKhông có chuỗi data1 <= data0, data2 <= data1 nên đây không phải thanh ghi dịch.\nKết quả là bốn D Flip-Flop song song cùng lấy mẫu một tín hiệu din.",
  "online2_5": "Đáp án A đúng vì ^A là reduction XOR của A=10011, có 3 bit 1 nên C=1.\nA[3:1] = 001, {2{C}} = 11 và B[2:0] = 110.\nNối lại được 00111110.",
  "online2_7": "Đáp án D đúng theo cách hiểu repeat(x) lấy số lần lặp là giá trị x lúc bắt đầu, tức 15.\nBa khối initial chạy song song, nhưng repeat đã xác định số vòng lặp theo x ban đầu.\nVì vậy lệnh $display được thực hiện 15 lần; giá trị in ra có thể phụ thuộc thứ tự mô phỏng.",
  "online2_8": "Đáp án A và B đúng theo phạm vi đề.\nChỉ số biến ở RHS có thể được tổng hợp thành MUX, còn chọn vị trí ở LHS có thể giống mạch giải mã/ghi chọn.\nassign là gán liên tục, thường dùng cho mạch tổ hợp và cũng có thể mô hình hóa latch nếu có hồi tiếp.\nC sai vì toán tử điều kiện không phải lúc nào cũng nhất thiết tạo MUX vật lý riêng.",
  "online2_9": "Đáp án C đúng vì hai cổng NOR được mắc hồi tiếp chéo với nhau.\nCấu trúc hồi tiếp d = ~(c|b) và c = ~(a|d) tạo phần tử nhớ 1 bit kiểu latch SR.\nKhông phải mạch so sánh vì có vòng hồi tiếp lưu trạng thái.",
  "online2_10": "Đáp án B đúng vì: Khối procedural chỉ thực thi một lần.\ninitial là khối thủ tục chạy một lần khi mô phỏng bắt đầu.\nNó thường dùng trong testbench để khởi tạo tín hiệu, tạo kích thích hoặc kết thúc mô phỏng.",
  "online2_12": "Đáp án B đúng vì: Tạo mạch từ đặc tả.\nSynthesis là quá trình chuyển đặc tả/mô tả HDL thành cấu trúc mạch phần cứng.\nNó khác với mô phỏng, vì mô phỏng chỉ kiểm tra hành vi còn tổng hợp tạo netlist logic.",
  "online2_13": "Đáp án C và D đúng vì trong procedural block chỉ được gán trực tiếp cho các biến procedural như reg/integer/logic.\nC đúng vì vế trái là B[3:0], mà B là biến kiểu reg nên có thể nhận gán trong always/initial.\nD đúng vì vế trái là C, mà C là integer nên cũng có thể nhận gán trong procedural block.\nA và B sai vì đều gán trực tiếp vào D; nếu D là wire thì không được gán trong procedural block, mà phải dùng assign hoặc nối qua cổng module.",
  "online2_14": "Đáp án B đúng vì: Trễ 5 đơn vị thời gian trước câu lệnh tiếp theo.\n#5 là delay 5 đơn vị thời gian trước khi thực hiện câu lệnh kế tiếp.\nĐây là thời gian trễ tương đối trong mô phỏng, không nhất thiết luôn là 5 ns.",
  "online2_15": "Đáp án D đúng vì reset bất đồng bộ active low phải đưa clear vào sensitivity list.\nVì clear tác động mức thấp nên dùng negedge clear.\nMạch đếm theo cạnh lên clk nên dùng posedge clk.\nDo đó biểu thức đúng là always @(posedge clk or negedge clear).",
  "online2_16": "Đáp án D đúng vì: Không có đáp án nào.\nrepeat(n) lặp một khối lệnh đúng n lần, với n là biểu thức số lần lặp.\nNó không phải vòng lặp vô hạn và cũng không lặp đến khi điều kiện đúng như while.",
  "online2_17": "Đáp án B đúng vì: Có.\nMạch tổ hợp thuần phải nhạy với mọi tín hiệu đầu vào ảnh hưởng đến ngõ ra.\nNếu thiếu input trong sensitivity list, mô phỏng có thể không cập nhật đúng và dễ suy ra latch ngoài ý muốn.",
  "online2_18": "Đáp án C đúng theo tính toán tuần tự trong initial block.\nBan đầu a=25, b=12, c=5, d=17; sau đó a=b+c=17, b=a-15=2.\nTiếp theo c=a+d=34 và d=c+d=34+17=51.",
  "online2_21": "Đáp án đúng là B và C.\nB sai vì khi gọi/instantiate một module nhiều lần, sau tổng hợp sẽ tạo ra nhiều instance phần cứng tương ứng, không phải chỉ một bản sao phần cứng.\nC sai vì trong Verilog chuẩn, một module không được chứa định nghĩa của một module khác bên trong nó; các module thường được định nghĩa tách rời rồi instantiate lại khi cần.\nA không sai vì khởi tạo X 4 lần sẽ tạo 4 bản sao/4 instance của module X.\nD không sai vì trong thiết kế có thể khởi tạo nhiều module/instance khác nhau trong cùng một module cha.",
  "online2_23": "Đáp án C và D đúng.\noutput reg result chỉ cho biết result là biến procedural được gán trong khối always, không có nghĩa bắt buộc tạo thanh ghi phần cứng.\nKhối always @(data) không dùng clock/cạnh clock, và cả nhánh if lẫn else đều gán giá trị cho result, nên khi tổng hợp sẽ tạo mạch tổ hợp.\nVì result là ngõ ra được điều khiển bởi logic tổ hợp, công cụ tổng hợp sẽ tạo một tín hiệu/net cho ngõ ra result.\nA sai vì không tạo mạch tuần tự hay phần tử lưu trữ; B sai vì vẫn có đáp án đúng.",
  "online2_24": "Đáp án C đúng vì lệnh forever clk1=!clk1; không có delay nên tạo vòng lặp vô hạn tại cùng thời điểm mô phỏng.\nCác câu lệnh phía sau forever không bao giờ được thực thi.\nVì vậy khối initial sẽ không đi tới repeat hay $finish.",
  "online2_25": "Đáp án B và C đúng.\nassign là phép gán liên tục, vế trái thường là net như wire và luôn bám theo biểu thức vế phải.\nNếu tạo hồi tiếp bằng assign, nó có thể mô hình hóa latch/hành vi lưu trạng thái; assign không gán trực tiếp cho reg.",
  "final2024_1": "Đáp án C đúng vì: Lỗi truyền hoặc lỗi xử lý dữ liệu.\nNếu khả năng chống nhiễu kém, mức logic có thể bị đọc sai hoặc chuyển trạng thái ngoài ý muốn.\nHậu quả trực tiếp là lỗi truyền dữ liệu hoặc lỗi xử lý dữ liệu.",
  "final2024_3": "Đáp án B đúng vì: FPGA chậm hơn 2–3 lần so với ASIC.\nFPGA dùng LUT và mạng nối lập trình được nên đường tín hiệu thường dài và kém tối ưu hơn ASIC.\nVì vậy FPGA thường chậm hơn ASIC trong cùng chức năng.",
  "final2024_4": "Đáp án C đúng vì C = A ^ B = 2'b10 ^ 2'b11 = 2'b01.\nPhép nối {A,B,C} ghép lần lượt A=10, B=11, C=01.\nDo đó kết quả là 101101.",
  "final2024_5": "Đáp án C đúng vì: Xác định thời gian trễ là 20 đơn vị thời gian (time unit).\n#20 là độ trễ mô phỏng 20 đơn vị thời gian theo `timescale đang dùng.\nNó không tự mặc định là ns nếu chưa xét time unit.",
  "final2024_6": "Đáp án A đúng vì 8'b10 là hằng nhị phân có độ rộng 8 bit.\nHai bit thấp là 10, các bit còn thiếu bên trái được thêm 0.\nDo đó dạng đầy đủ là 8'b00000010.",
  "final2024_8": "Đáp án E đúng vì đoạn mô tả không hợp lệ.\nA và B được khai báo wire nhưng lại bị gán trực tiếp bằng câu lệnh thủ tục A=1, B=A ngoài assign/always.\nwire cần được gán bằng assign liên tục hoặc điều khiển bởi cổng/module, nên không thể kết luận B theo đoạn code này.",
  "final2024_10": "Đáp án D đúng vì 1024 byte nghĩa là 1024 ô nhớ, mỗi ô rộng 8 bit.\nTrong Verilog, reg [7:0] mem [1023:0] là mảng 1024 phần tử 8 bit.\nCác lựa chọn khác sai cú pháp hoặc đảo nhầm độ rộng phần tử với số phần tử.",
  "final2024_11": "Đáp án C đúng vì: reg.\nTín hiệu được gán trong always/initial phải là reg trong Verilog truyền thống.\nreg là biến lưu giá trị mô phỏng và có thể tổng hợp thành FF, latch hoặc logic tùy cách mô tả.",
  "final2024_12": "Đáp án B đúng vì b được khai báo theo chiều bit [3:0].\nTrong Verilog, khi chọn một dải bit theo kiểu part-select thông thường, cần viết đúng chiều khai báo của vector.\nBiểu thức b[0:3] bị đảo chiều so với khai báo wire [3:0] b, nên không hợp lệ theo phạm vi đề.\nA hợp lệ vì gán toàn bộ vector b cho a.\nTheo đáp án gốc của đề, lỗi được xác định ở lựa chọn B.",
  "final2024_13": "Đáp án D đúng vì ngõ ra o được khai báo là output wire, nên cách mô tả phù hợp là dùng phép gán liên tục assign.\nToán tử điều kiện s ? i[0] : i[1] hoạt động như bộ chọn: nếu s = 1 thì o = i[0], nếu s = 0 thì o = i[1].\nVì vậy câu lệnh assign o = s ? i[0] : i[1]; mô tả đúng mạch đa hợp 2 sang 1 theo đề.\nA sai vì không thể viết assign if ... else ...; C sai vì thiếu assign hoặc khối procedural; B không phải dạng mô tả mux 2:1 đúng, rõ ràng theo cú pháp chuẩn trong các lựa chọn.",
  "final2024_15": "Đáp án B đúng vì D được gán bằng ~Q nên mỗi cạnh clock Q sẽ đảo trạng thái.\nMột D Flip-Flop có D=~Q tạo mạch chia tần số 2.\nReset đưa Q về 0 trước khi bắt đầu đếm/đảo trạng thái.",
  "final2024_16": "Đáp án A đúng vì giá trị reset của Q nằm trực tiếp ở câu Q <= 1'b0.\nMuốn Q bắt đầu bằng 1 khi reset tác động thì đổi dòng đó thành Q <= 1'b1.\nĐổi Qout hoặc D không thay đổi trạng thái reset bên trong của Q.",
  "final2024_17": "Đáp án A đúng vì always có cả posedge clk và cạnh reset trong sensitivity list.\nReset được kiểm tra bên trong khối always nên là reset bất đồng bộ theo cấu trúc đề cho.\nQ nhận D ở cạnh clock, vì vậy phần tử chính là D Flip-Flop.",
  "final2024_18": "Đáp án A đúng vì Qout chỉ lên 1 khi Q1=1 và Q0=1 là phép AND logic theo bit.\nBiểu thức assign Qout = Q1 & Q0; mô tả đúng điều kiện đó.\nXOR chỉ lên 1 khi hai bit khác nhau, còn OR/+ không diễn tả điều kiện 'cả hai cùng cao'.",
  "final2024_19": "Đáp án C đúng vì: FPGA yêu cầu dự phòng để cấu hình lại.\nFPGA cần SRAM cấu hình, switch lập trình và tài nguyên dự phòng để tái cấu hình.\nNhững phần phụ trợ này làm số transistor cho mỗi hàm logic nhiều hơn ASIC.",
  "final2024_20": "Đáp án E đúng vì: Tapeout.\nCâu hỏi thuộc quy trình thiết kế vi mạch từ mô tả, mô phỏng, tổng hợp đến bố trí và kiểm tra.\nPhương án đúng khớp với nhiệm vụ của tầng được hỏi trong quy trình.",
  "final2024_22": "Đáp án D đúng vì CPLD thường gồm nhiều khối SPLD/PAL-like được nối với nhau.\nCác khối này liên kết qua mạng kết nối bên trong lập trình được.\nNó khác PLA đơn lẻ chỉ gồm mảng AND/OR lập trình.",
  "final2024_23": "Đáp án E đúng vì cả C và D đều mô tả dịch phải 2 bit.\nA >> 2 dịch các bit sang phải và thêm 0 ở bên trái với kiểu không dấu.\n{2'b00, A[7:2]} cũng tạo đúng kết quả sau khi dịch phải 2 bit.",
  "final2024_24": "Đáp án B đúng vì Flip-Flop D lấy mẫu ngõ vào D tại cạnh tác động của clock và lưu vào Q.\nCú pháp always @(posedge clk) mô tả khối chạy tại cạnh lên của clock.\nVì vậy Q nhận giá trị của D tại thời điểm cạnh lên clock xuất hiện.\nA sai cú pháp/không phải mô tả bằng khối always.\nC và D dùng @(clk), tức kích hoạt khi clk thay đổi, không chỉ riêng cạnh lên.\nTrong thiết kế tuần tự thực tế thường ưu tiên dùng <=, nhưng trong các lựa chọn thì B đúng nhất.",
  "final2024_27": "Đáp án D đúng vì kết quả là 64.\nTrong Verilog, toán tử ** là phép lũy thừa.\nA = 8'b100 có giá trị nhị phân 100, tức là 4 ở hệ thập phân.\nB = 4'b11 có giá trị nhị phân 11, tức là 3 ở hệ thập phân.\nVì vậy A ** B = 4 ** 3 = 64.",
  "final2024_29": "Đáp án B đúng vì next-state của thanh ghi dịch phải sẽ đưa Inputs vào bit cao, còn state_reg[7:1] dịch xuống các bit thấp.\nNext State Logic nên viết bằng assign tổ hợp, không đặt trong always cạnh clock.\nDo đề gốc có hình ảnh nên cần đối chiếu lại hướng dịch trong sơ đồ.\nCần kiểm tra lại đáp án.",
  "final2024_31": "Đáp án C đúng vì trong Verilog có thể dùng cổng primitive để mô tả cổng AND.\nCú pháp primitive của cổng AND là: and (output, input1, input2, input3, ...);\nVới module có ngõ ra F và các ngõ vào x, y, z, mô tả đúng là: and (F, x, y, z);\nA sai vì không viết assign and(...).\nB sai vì dùng always và cách viết x and y and z không đúng cú pháp Verilog.\nD chưa đủ vì chỉ là biểu thức, không có assign để gán kết quả ra F.",
  "final2024_32": "Đáp án D đúng vì reset đồng bộ chỉ được kiểm tra tại cạnh clock.\nDo đó sensitivity list chỉ cần posedge clk, không đưa reset vào danh sách sự kiện.\nBên trong khối always, nếu reset = 1 thì y được gán về 0; nếu reset = 0 thì y tăng lên 1 sau mỗi cạnh lên của clock.\nA sai vì có posedge reset trong sensitivity list nên mô tả reset bất đồng bộ.\nB và C không mô tả đúng mạch đồng bộ theo cạnh clock; E sai vì không có tín hiệu reset.",
  "main_2": "Đáp án B đúng vì: 3.\nFront-End thường gồm mô tả hệ thống, mô tả RTL/HDL và tổng hợp logic.\nVì vậy phần việc của người thiết kế chiếm 3 tầng đầu trong quy trình của đề.",
  "main_4": "Đáp án A đúng vì tầng thứ nhất là bước mô tả/xác định ban đầu của hệ thống.\nTầng này gồm viết chương trình hệ thống, viết chương trình mô phỏng và khai báo các thông số thiết kế.\nĐây là cơ sở đầu vào cho các bước mô phỏng, đánh giá và tổng hợp phía sau.\nB thuộc tầng mô phỏng/đánh giá; C thuộc tầng tổng hợp/tầng 3; D thuộc bước đi dây Back-End.",
  "main_5": "Đáp án B đúng vì tầng thứ hai có nhiệm vụ thực hiện mô phỏng và đánh giá.\nSau khi đã có mô tả ban đầu ở tầng 1, thiết kế cần được mô phỏng để kiểm tra hoạt động logic/chức năng.\nBước đánh giá giúp phát hiện lỗi và xác nhận thiết kế trước khi chuyển sang tầng tổng hợp.\nA thuộc tầng thứ nhất; C là nhiệm vụ của tầng tổng hợp/tầng 3; D thuộc giai đoạn đi dây ở Back-End.",
  "main_6": "Đáp án C đúng vì tầng thứ ba có nhiệm vụ tổng hợp các thành phần của thiết kế.\nỞ tầng này, chương trình/mô tả thiết kế, các ràng buộc thời gian và vị trí các ô thành phần được xử lý để chuẩn bị cho các bước sau.\nA thuộc tầng mô tả ban đầu; B thuộc tầng mô phỏng/đánh giá; D thuộc giai đoạn đi dây tự động.",
  "main_7": "Đáp án A đúng vì: Xác định bố cục ban đầu trước khi phân tích các yếu tố thời gian.\nCâu hỏi thuộc quy trình thiết kế vi mạch từ mô tả, mô phỏng, tổng hợp đến bố trí và kiểm tra.\nPhương án đúng khớp với nhiệm vụ của tầng được hỏi trong quy trình.",
  "main_8": "Đáp án B đúng vì: Đi dây tự động cho hệ thống.\nCâu hỏi thuộc quy trình thiết kế vi mạch từ mô tả, mô phỏng, tổng hợp đến bố trí và kiểm tra.\nPhương án đúng khớp với nhiệm vụ của tầng được hỏi trong quy trình.",
  "main_13": "Đáp án A đúng vì tầng thứ sáu gồm 2 công đoạn.\nHai công đoạn đó là: kiểm tra các hoạt động logic của hệ thống và kiểm tra kết quả cuối cùng sau thiết kế/tổng hợp.\nĐây là bước thuộc giai đoạn kiểm tra, nhằm xác nhận mạch hoạt động đúng trước khi hoàn thiện.\nCác đáp án 3, 4, 1 không khớp với số công đoạn của tầng thứ sáu trong quy trình.",
  "main_15": "Đáp án B đúng vì: Là kết quả cuối cùng của quá trình thiết kế hoặc dưới dạng PCB trước khi sản xuất.\nTapeout là dữ liệu/kết quả cuối cùng được chuyển sang sản xuất chip hoặc triển khai vật lý.\nNó đánh dấu việc thiết kế đã hoàn tất và sẵn sàng cho bước chế tạo/đưa ra sản phẩm.",
  "main_17": "Đáp án D đúng vì: Phương án C sai.\nBack-End tập trung vào bố trí vật lý, đi dây, phân tích timing và kiểm tra kết quả cuối.\nCác bước này diễn ra sau khi thiết kế logic đã được mô tả/tổng hợp.",
  "main_19": "Đáp án C đúng vì: Cả A, B đều đúng.\nMạch tích hợp có ưu điểm diện tích nhỏ, tốc độ cao, độ tin cậy tốt và tiêu thụ công suất thấp hơn mạch rời rạc.\nDo nhiều phần tử được tích hợp trên cùng chip nên giảm dây nối và ký sinh.",
  "main_20": "Đáp án C đúng vì transistor đầu tiên được công bố vào năm 1947 tại Bell Labs.\nĐây là mốc mở đầu kỷ nguyên linh kiện bán dẫn transistor.\nCác năm khác không phải mốc ra đời transistor đầu tiên.",
  "main_22": "Đáp án D đúng vì: Cả A và B đều đúng.\nĐịnh luật Moore thường phát biểu rằng mật độ/số transistor trên chip tăng rất nhanh theo thời gian, thường xấp xỉ gấp đôi sau khoảng 18-24 tháng.\nTrong phạm vi đề, phương án được chọn mô tả đúng xu hướng tăng mật độ tích hợp.",
  "main_23": "Đáp án B đúng vì: 2300 transistor – 1MHz.\nIntel 4004 ra đời năm 1971 và thường được nêu với khoảng 2300 transistor.\nTốc độ xung nhịp nằm cỡ MHz, nên phương án 2300 transistor - 1 MHz phù hợp với dữ liệu đề.",
  "main_24": "Đáp án A đúng vì: 10.\nSSI là Small Scale Integration, mức tích hợp nhỏ.\nTrong bảng phân loại của đề, SSI ứng với khoảng 10 transistor/cổng phần tử.",
  "main_27": "Đáp án D đúng vì: >10.000.\nCâu hỏi kiểm tra phân loại mức độ tích hợp IC theo số lượng transistor.\nVLSI là mức rất lớn nên nằm trên LSI, thường lớn hơn 10.000 transistor theo bảng của đề.",
  "main_28": "Đáp án A đúng vì: Silic -> Silic wafer -> Patterned Silicon Wafer -> Unpackaged Die -> Packaged Die -> Test.\nQuy trình sản xuất đi từ silicon thô, tạo wafer, tạo mẫu mạch trên wafer, tách die, đóng gói rồi kiểm tra.\nThứ tự này phản ánh đúng dòng chế tạo IC từ vật liệu đến chip hoàn chỉnh.",
  "main_30": "Đáp án A đúng vì: PLDs.\nFPGA thuộc nhóm PLD vì người dùng có thể lập trình/cấu hình chức năng logic sau khi chế tạo.\nASIC là mạch chuyên dụng cố định nên không cùng nhóm với FPGA.",
  "main_31": "Đáp án A đúng vì: Programmable Logic Devices.\nPLD là viết tắt của Programmable Logic Device, tức thiết bị logic lập trình được.\nTên này chỉ nhóm vi mạch có thể cấu hình logic sau khi sản xuất.",
  "main_32": "Đáp án A đúng vì: Application-Specific Integrated Circuit.\nASIC là mạch tích hợp chuyên dụng cho một ứng dụng cụ thể.\nNó tối ưu hơn FPGA nhưng kém linh hoạt vì không cấu hình lại như FPGA.",
  "main_33": "Đáp án C đúng vì: Field Programmable Gate Array.\nFPGA hiện thực logic bằng tài nguyên lập trình được như LUT, CLB và mạng nối cấu hình.\nVì vậy đáp án chọn khớp với bản chất cấu trúc FPGA.",
  "main_34": "Đáp án A đúng vì PLD gồm các nhóm thiết bị logic lập trình được như SPLD, CPLD và FPGA.\nSPLD là loại đơn giản, CPLD phức tạp hơn, FPGA có tài nguyên LUT/CLB lớn.\nASIC không thuộc PLD vì được chế tạo chuyên dụng, không cấu hình lại như FPGA.",
  "main_35": "Đáp án D đúng vì các mạch tích hợp cho một ứng dụng cụ thể thuộc nhóm ASIC.\nASIC thường được chia thành hai nền tảng chính là Full-Custom và Semi-Custom.\nFull-Custom cho phép thiết kế tối ưu sâu ở mức transistor/layout, còn Semi-Custom dùng cell, thư viện hoặc cấu trúc có sẵn để rút ngắn thời gian thiết kế.\nSPLD, CPLD và FPGA thuộc nhóm logic lập trình được, không phải nền tảng ASIC chuyên dụng theo câu hỏi.",
  "main_37": "Đáp án D đúng vì: Cả ba phương án không sai.\nFPGA linh hoạt nhưng thường chậm hơn ASIC, tốn diện tích và công suất hơn do tài nguyên lập trình được.\nVì các hạn chế trong các phương án đều đúng nên chọn phương án tổng hợp.",
  "main_38": "Đáp án D đúng vì: Cả ba phương án trên không sai.\nASIC được thiết kế chuyên dụng nên có hiệu suất cao, tốc độ tốt và tiêu thụ công suất thấp.\nKhi sản xuất số lượng lớn, chi phí trên mỗi chip có thể rẻ hơn FPGA.",
  "main_39": "Đáp án D đúng vì: Cả ba phương án trên không thể sai.\nASIC cố định sau khi chế tạo, thời gian phát triển lâu và chi phí thiết kế/mặt nạ cao.\nVì các ý trong đáp án đều là hạn chế của ASIC nên chọn phương án tổng hợp.",
  "main_40": "Đáp án A đúng vì: Hiệu suất cao, tiêu thụ điện năng thấp, giá thành rẻ với số lượng lớn.\nASIC được thiết kế chuyên dụng nên có hiệu suất cao, tốc độ tốt và tiêu thụ công suất thấp.\nKhi sản xuất số lượng lớn, chi phí trên mỗi chip có thể rẻ hơn FPGA.",
  "main_43": "Đáp án A đúng vì thiết kế FPGA kết thúc bằng bitstream dùng để cấu hình chip.\nBitstream quyết định LUT, FF và các kết nối lập trình bên trong FPGA.\nASIC kết thúc bằng dữ liệu layout/tapeout, không phải dòng bit cấu hình.",
  "main_44": "Đáp án A đúng vì: Simple Programmable Logic Device.\nPLD là viết tắt của Programmable Logic Device, tức thiết bị logic lập trình được.\nTên này chỉ nhóm vi mạch có thể cấu hình logic sau khi sản xuất.",
  "main_46": "Đáp án A đúng vì: Sử dụng một mảng các tiếp điểm (switch,..), chúng được lặp trình bằng cách tác động vào các tiếp điểm.\nMạch tích hợp có ưu điểm diện tích nhỏ, tốc độ cao, độ tin cậy tốt và tiêu thụ công suất thấp hơn mạch rời rạc.\nDo nhiều phần tử được tích hợp trên cùng chip nên giảm dây nối và ký sinh.",
  "main_47": "Đáp án B đúng vì GAL sử dụng các ô nhớ EEPROM để lưu cấu hình các điểm nối/lập trình.\nGAL là phiên bản cải tiến của PAL, thay cơ chế lập trình một lần bằng bộ nhớ EEPROM có thể xóa và ghi lại.\nNhờ đó GAL có thể lập trình lại nhiều lần, linh hoạt hơn PAL.\nA mô tả kiểu dùng tiếp điểm/switch lập trình trực tiếp, chưa đúng đặc trưng GAL.\nC là hệ quả của việc dùng EEPROM nhưng B nêu đúng đặc điểm cấu trúc chính hơn.",
  "main_48": "Đáp án B đúng vì phương pháp nhóm các số 0 ở ngõ ra là Product of Sums, viết tắt là POS.\nPOS biểu diễn hàm logic dưới dạng tích của các tổng.\nMỗi tổ hợp ngõ vào làm hàm bằng 0 sẽ tương ứng với một maxterm.\nSOP hay Sum of Products thường dùng khi nhóm các số 1 ở ngõ ra.\nVì đề hỏi nhóm các số 0 nên chọn Product of Sums.",
  "main_49": "Đáp án A đúng vì: Sum of Product.\nMạch tích hợp có ưu điểm diện tích nhỏ, tốc độ cao, độ tin cậy tốt và tiêu thụ công suất thấp hơn mạch rời rạc.\nDo nhiều phần tử được tích hợp trên cùng chip nên giảm dây nối và ký sinh.",
  "main_53": "Đáp án A là phát biểu sai theo dữ liệu đề vì PAL truyền thống thường lập trình một lần.\nGAL dùng EEPROM nên có thể xóa và lập trình lại nhiều lần.\nVì vậy nói PAL có thể lập trình nhiều lần là không đúng trong phạm vi câu hỏi.",
  "main_55": "Đáp án C đúng vì PLA có tầng đầu vào tạo cả tín hiệu không đảo và tín hiệu đảo.\nSau đó mảng AND lập trình tạo các product-term.\nCuối cùng mảng OR lập trình cộng các product-term để tạo hàm ngõ ra.",
  "main_56": "Đáp án B đúng vì CPLD là Complex Programmable Logic Device.\nCPLD thường được cấu tạo từ nhiều khối logic kiểu SPLD/PAL/GAL.\nCác khối này được kết nối với nhau thông qua mạng liên kết hoặc mảng nối dây lập trình được.\nSPLD chỉ là thiết bị logic lập trình đơn giản riêng lẻ.\nFPGA dùng cấu trúc CLB/LUT linh hoạt hơn, còn PLA là mảng AND/OR lập trình, không phải tập hợp các SPLD.",
  "main_58": "Đáp án A đúng vì: Configurable Logic Block.\nCLB là Configurable Logic Block.\nĐây là khối logic có thể cấu hình trong FPGA, thường chứa LUT, FF và mạch chọn.",
  "main_59": "Đáp án B đúng vì: Look-Up Table.\nLUT là Look-Up Table.\nNó lưu bảng chân trị để hiện thực hàm logic theo các ngõ vào.",
  "main_64": "Đáp án B đúng vì Full Custom ASIC là công nghệ chế tạo IC mất nhiều thời gian nhất.\nVới Full Custom ASIC, các thành phần thường được thiết kế chi tiết ở mức transistor/layout thay vì dùng sẵn thư viện cell.\nQuá trình này cần tối ưu thủ công về diện tích, tốc độ, công suất và kiểm tra vật lý nên rất tốn thời gian.\nGate Array và Standard Cell ASIC dùng phần tử/thư viện có sẵn nên nhanh hơn.\nFPGA/CPLD là linh kiện lập trình được nên thời gian triển khai ngắn hơn nhiều.",
  "main_65": "Đáp án B đúng vì Gate Array ASIC có quá trình chế tạo đơn giản hơn các loại ASIC khác.\nVới Gate Array, các lớp transistor/cell cơ bản đã được chế tạo sẵn.\nKhi thiết kế, nhà sản xuất chủ yếu chỉ cần tùy chỉnh các lớp nối dây để tạo mạch mong muốn.\nFull-custom ASIC phức tạp nhất vì phải thiết kế sâu đến mức transistor/layout.\nStandard cell ASIC cũng cần placement và routing nhiều cell chuẩn nên phức tạp hơn Gate Array.",
  "main_68": "Đáp án C đúng vì khi đánh giá công nghệ chế tạo IC, ta cần xét mối tương quan giữa tài nguyên chip, tốc độ chip, sức mạnh xử lý và giá thành.\nCác thông số này thường có quan hệ đánh đổi với nhau.\nChip có nhiều tài nguyên, tốc độ cao và sức mạnh lớn thường có chi phí chế tạo cao hơn.\nNgược lại, công nghệ giá rẻ hơn thường bị giới hạn về tài nguyên hoặc hiệu năng.\nVì vậy đáp án C liệt kê đúng nhóm thông số cần so sánh.",
  "main_69": "Đáp án A đúng vì Standard Cell ASIC là công nghệ thiết kế dựa trên các cell/cổng logic chuẩn có sẵn trong thư viện.\nCác cell chuẩn có thể là AND, OR, NOT, Flip-Flop, MUX... và được ghép nối để tạo thành mạch hoàn chỉnh.\nVì thiết kế được xây dựng từ các cell/cổng chuẩn nên được xem là thiết kế ở cấp độ cổng.\nFull Custom ASIC thiết kế sâu hơn ở mức transistor/layout.\nGate Array ASIC chủ yếu tùy chỉnh lớp nối dây, còn FPGA/CPLD là linh kiện lập trình được.",
  "main_70": "Đáp án C đúng vì FPGA dùng các khối logic cấu hình được, bên trong thường có LUT.\nLUT, tức Look-Up Table, lưu bảng chân trị để hiện thực các hàm logic tổ hợp.\nKhi nạp cấu hình, LUT sẽ tạo ra hàm logic mong muốn theo thiết kế.\nPLA/PAL dùng mảng AND/OR lập trình, CPLD thường dựa trên các khối kiểu PAL/GAL.\nVì vậy thiết bị có tế bào logic dùng LUT là FPGA.",
  "main_72": "Đáp án D đúng vì với LUT 3 ngõ vào, LUT chỉ cần lưu bảng chân trị gồm 2^3 = 8 giá trị.\nLUT thực hiện hàm logic bằng cách dùng các ngõ vào để tra bảng giá trị đã lưu, nên phần kết nối bên trong tương đối cố định theo cấu trúc LUT.\nTrong khi đó, PAL dùng mảng AND/OR lập trình nên cần nhiều mối nối lập trình để tạo các tích và tổng.\nVì vậy trong phạm vi so sánh của đề, cấu trúc LUT dùng ít bộ nhớ/tài nguyên nối hơn PAL với 3 ngõ vào.",
  "main_73": "Đáp án B đúng vì theo cấu trúc nối dây lập trình trong FPGA, một điểm giao giữa đường ngang và đường dọc cần các transistor chuyển mạch để đóng/ngắt kết nối.\nCác ô nhớ SRAM lưu bit cấu hình, dùng để điều khiển transistor chuyển mạch bật hoặc tắt.\nTheo cấu trúc trong tài liệu đề, một điểm nối như vậy dùng 6 transistor chuyển mạch và 6 ô nhớ SRAM.\nCác đáp án 7, 4 hoặc 5 transistor/SRAM không khớp với số phần tử của cấu trúc nối dây đã cho.",
  "main_74": "Đáp án B đúng vì khả năng lập trình của CPLD đến từ các switch/kết nối có điều khiển.\nCác switch này quyết định đường tín hiệu nào được nối giữa các khối logic.\nNếu chỉ là dây cố định thì thiết bị sẽ không còn khả năng lập trình linh hoạt.",
  "main_75": "Đáp án D đúng vì: Full custom asic.\nMạch tích hợp có ưu điểm diện tích nhỏ, tốc độ cao, độ tin cậy tốt và tiêu thụ công suất thấp hơn mạch rời rạc.\nDo nhiều phần tử được tích hợp trên cùng chip nên giảm dây nối và ký sinh.",
  "main_78": "Đáp án A đúng vì: Hardware Description Language.\nHDL là Hardware Description Language.\nĐây là ngôn ngữ dùng để mô tả, mô phỏng và tổng hợp phần cứng số.",
  "main_85": "Đáp án D đúng vì: module <module_name> (<module_terminal_list>);.\nCú pháp khai báo module gồm từ khóa module, tên module, danh sách cổng trong ngoặc và dấu chấm phẩy.\nSau đó mới khai báo input/output và phần thân module.",
  "main_87": "Đáp án A đúng vì định danh Verilog không được bắt đầu bằng chữ số hoặc dấu trừ.\nTheo phạm vi đề, tên người dùng cũng không bắt đầu bằng ký hiệu $.\nDấu _ có thể đứng đầu định danh nên các phương án chứa _ ở đầu không phải lỗi.",
  "main_89": "Đáp án A đúng vì _$Counter_Flipflop_ chỉ dùng ký tự cho phép như _, $, chữ cái.\nCác lựa chọn khác chứa dấu gạch ngang hoặc ký tự lạ nên không hợp lệ.\nTrong Verilog, định danh thông thường không được chứa dấu - vì dễ bị hiểu là phép trừ.",
  "main_90": "Đáp án B đúng vì // dùng để chú thích một dòng trong Verilog.\nMọi nội dung sau // trên cùng dòng sẽ bị trình biên dịch bỏ qua.\n/* ... */ dùng cho chú thích nhiều dòng hoặc một đoạn khối.",
  "main_91": "Đáp án A đúng vì /* ... */ dùng để chú thích một khối nhiều dòng.\nNội dung nằm giữa dấu mở /* và dấu đóng */ sẽ không được biên dịch.\nDấu // chỉ có tác dụng đến hết dòng hiện tại.",
  "main_92": "Đáp án D không hợp lệ vì Verilog không hỗ trợ chú thích lồng nhau.\nCụm /* Nesting /* comments */ do not work */ sẽ bị đóng ở dấu */ đầu tiên.\nPhần còn lại có thể trở thành mã không hợp lệ.",
  "main_95": "Đáp án C đúng vì trong Verilog, X biểu diễn giá trị không xác định hoặc mức logic không rõ ràng.\nGiá trị này thường xuất hiện khi tín hiệu chưa được khởi tạo, bị xung đột driver hoặc kết quả phép toán không xác định.\n0 và 1 là hai mức logic xác định.\nZ là trạng thái tổng trở cao, không phải mức logic không rõ ràng.",
  "main_98": "Đáp án A đúng vì 8'ha5 là số hex 8 bit gồm hai chữ số A và 5.\nA tương ứng 1010, còn 5 tương ứng 0101.\nGhép lại được 1010_0101.",
  "main_99": "Đáp án B đúng vì mỗi chữ số bát phân biểu diễn 3 bit.\nTrong 12'o3xz7: 3 = 011, x mở rộng thành xxx, z mở rộng thành zzz, 7 = 111.\nDo đó dạng bit là 011|xxx|zzz|111; đề sắp thứ tự x/z theo đáp án đã cho cần kiểm tra lại nếu khác ký tự gốc.\nCần kiểm tra lại đáp án.",
  "main_100": "Đáp án B đúng vì Verilog cho phép dùng dấu gạch dưới _ để tách nhóm chữ số cho dễ đọc.\nDấu _ không làm thay đổi giá trị của hằng số.\nCác dấu như -, = hoặc . không dùng để nối nhóm chữ số trong hằng số Verilog.",
  "main_101": "Đáp án D đúng vì 12'h0724 không cùng giá trị với các biểu diễn còn lại.\nA = 12'b000_111_010_100 = 0001_1101_0100 = 0x1D4.\nB = 12'b0001_1101_0100 cũng bằng 0x1D4.\nC = 12'o7_24 = octal 724 = 0x1D4.\nD = 12'h0724 = 0x724, khác 0x1D4 nên là đáp án không cùng biểu diễn một số.",
  "main_102": "Đáp án D đúng vì mở rộng bằng cách lặp lại MSB là sign/strength extension theo bit cao nhất.\nNếu MSB là 0, X hoặc Z thì các bit thêm vào lặp lại đúng giá trị đó.\nDo đó phép mở rộng không làm thay đổi ý nghĩa biểu diễn ban đầu theo quy tắc đề.",
  "main_103": "Đáp án D đúng vì khi xét biểu diễn nhị phân không dấu, bit có nghĩa cao nhất MSB của một số khác 0 là 1.\nViệc thêm các số 0 ở bên trái MSB chỉ mở rộng độ rộng bit, không làm thay đổi giá trị số.\nVí dụ 101 và 000101 đều biểu diễn cùng một giá trị nếu xem là số không dấu.\nX và Z không phải giá trị logic xác định, còn 0 không phải bit có nghĩa cao nhất của một số khác 0 trong cách hiểu của câu hỏi.",
  "main_104": "Đáp án A đúng vì 4'b1 được mở rộng thành 4'b0001.\nCác dạng còn lại chứa x ở các bit bên trái, ví dụ xxx1, nên không cùng giá trị xác định với 0001.\nVì vậy 4'b1 không đồng biểu diễn với các giá trị có X.",
  "main_105": "Đáp án C đúng vì 4'b01 được mở rộng thành 4'b0001.\nCác lựa chọn 4'b1x, 4'b0_1x và 4'b001x đều có bit thấp là x nên cùng nhóm biểu diễn có trạng thái không xác định.\nDo đó 4'b01 không đồng biểu diễn với nhóm có x ở bit cuối.",
  "main_107": "Đáp án C đúng vì khi bỏ qua cơ số trong số Verilog, giá trị mặc định được hiểu là thập phân.\nVí dụ 123 được hiểu là số decimal 123, không phải nhị phân hay hex.\nMuốn chỉ cơ số khác phải viết dạng 'b, 'o, 'h hoặc có size kèm radix.",
  "main_109": "Đáp án C đúng vì cú pháp khai báo tham số là parameter tên = giá_trị;.\nparameter var_timer=2'b00; dùng đúng từ khóa parameter và gán một hằng nhị phân.\nCác lựa chọn khác sai từ khóa hoặc thiếu dấu chấm phẩy.",
  "main_110": "Đáp án C đúng vì tín hiệu Verilog có thể hiểu vừa là kết nối phần cứng vừa là đối tượng lưu/biểu diễn giá trị trong mô phỏng.\nNet như wire biểu diễn dây nối, còn variable như reg biểu diễn biến nhận gán thủ tục.\nVì vậy cả hai cách mô tả trong A và B đều không sai.",
  "main_111": "Đáp án C đúng vì tín hiệu trong Verilog có thể là net hoặc variable.\nNet đại diện dây/kết nối như wire, còn variable đại diện đối tượng nhận gán trong procedural block như reg.\nHai nhóm này có cách gán và sử dụng khác nhau.",
  "main_112": "Đáp án C đúng vì cú pháp khai báo tín hiệu trong Verilog thường có dạng type [range] signal_name;.\nTrong đó type là kiểu tín hiệu như wire, reg hoặc integer.\n[range] dùng để xác định độ rộng bus/vector, ví dụ [7:0].\nsignal_name là tên tín hiệu cần khai báo.\nCác đáp án dùng ngoặc tròn () hoặc ngoặc nhọn {} không đúng cú pháp khai báo range trong Verilog.",
  "main_114": "Đáp án D đúng vì Wire, Wand/Wor và Tri đều là các loại đường dây net trong Verilog.\nwire là net thông dụng, dùng để biểu diễn đường nối phần cứng giữa các module, cổng hoặc phép gán assign.\nwand và wor là các net có cơ chế phân giải nhiều nguồn điều khiển theo wired-AND hoặc wired-OR.\ntri là net ba trạng thái, có thể mang giá trị 0, 1 hoặc trạng thái tổng trở cao Z.\nVì A, B và C đều là các loại net nên chọn D.",
  "main_115": "Đáp án D đúng vì: Cả A, B và C.\nTín hiệu được gán trong always/initial phải là reg trong Verilog truyền thống.\nreg là biến lưu giá trị mô phỏng và có thể tổng hợp thành FF, latch hoặc logic tùy cách mô tả.",
  "main_117": "Đáp án B đúng theo cách làm tròn khi gán số thực 2.9 cho biến integer trong phạm vi đề.\ninteger chỉ lưu số nguyên, nên phần thập phân không được giữ nguyên như kiểu real.\nKết quả được làm tròn thành 3 theo đáp án đề.\nCần kiểm tra lại đáp án vì một số công cụ có thể xử lý ép kiểu khác nhau.",
  "main_119": "Đáp án D đúng vì khi dùng mảng cần chú ý khả năng truy xuất phần tử/trường, giới hạn kiểu dữ liệu và số chiều được hỗ trợ theo chuẩn đang dùng.\nTrong Verilog truyền thống, mảng có một số hạn chế so với SystemVerilog.\nVì các ý A, B, C đều là điểm cần lưu ý theo đề nên chọn D.",
  "main_120": "Đáp án A đúng vì chuỗi trong Verilog thường được lưu bằng reg vector.\nMỗi ký tự chiếm 8 bit ASCII, nên cần khai báo reg đủ rộng để chứa toàn bộ chuỗi.\nwire/bus/array không phải kiểu thường dùng trực tiếp để khai báo string trong phạm vi đề.",
  "main_124": "Đáp án B đúng vì: OR hai phần tử.\nToán tử || là OR logic, xét mỗi toán hạng theo đúng/sai.\nNếu có X tham gia và kết quả không thể xác định chắc chắn thì kết quả có thể là X.",
  "main_125": "Đáp án A đúng vì: Đảo bit một phần tử.\nToán tử ! là NOT logic, đảo giá trị đúng/sai của toàn biểu thức.\nNó khác với ~ là đảo từng bit.",
  "main_126": "Đáp án C đúng vì: AND lần lượt các bit.\nToán tử & là AND theo từng bit khi dùng giữa hai vector.\nNếu dùng một toán hạng, nó là reduction AND.",
  "main_127": "Đáp án D đúng vì: OR lần lượt các bit.\nToán tử | là OR theo từng bit khi dùng giữa hai vector.\nNếu dùng một toán hạng, nó là reduction OR.",
  "main_129": "Đáp án D đúng vì: XNOR lần lượt các bit.\n~^ hoặc ^~ là XNOR theo từng bit.\nKết quả bằng 1 tại bit mà hai toán hạng giống nhau.",
  "main_133": "Đáp án C đúng vì: X.\nToán tử || là OR logic, xét mỗi toán hạng theo đúng/sai.\nNếu có X tham gia và kết quả không thể xác định chắc chắn thì kết quả có thể là X.",
  "main_134": "Đáp án C đúng vì ~ là toán tử đảo từng bit.\nVới a=4'b1010, đảo từng bit sẽ được 0101.\nĐây không phải NOT logic, nên kết quả không chỉ là 0 hoặc 1.",
  "main_135": "Đáp án B đúng vì |a là reduction OR trên tất cả bit của a.\na=4'b1010 có ít nhất một bit bằng 1 nên OR rút gọn cho kết quả 1.\nNếu tất cả bit đều 0 thì kết quả mới là 0.",
  "main_136": "Đáp án A đúng vì: NOR lần lượt các bit.\n~| là phép NOR reduction/theo bit tùy ngữ cảnh.\nNó là phủ định của OR, nên chỉ bằng 1 khi tất cả bit/ngõ vào đều bằng 0.",
  "main_137": "Đáp án B đúng vì: NAND lần lượt các bit.\n~& là phép NAND reduction/theo bit tùy ngữ cảnh.\nNó là phủ định của phép AND, nên chỉ bằng 0 khi toàn bộ điều kiện AND bằng 1.",
  "main_138": "Đáp án A đúng vì: 0010.\nToán tử >> dịch các bit sang phải.\nCác bit thấp bị bỏ, còn phía bên trái được điền 0 với số không dấu.",
  "main_139": "Đáp án A đúng vì toán tử nối chuỗi trong Verilog dùng cặp ngoặc nhọn { }.\nCác toán hạng được đặt theo thứ tự từ trái sang phải: {op1, op2, ...}.\nDấu ngoặc tròn hoặc ngoặc vuông không phải cú pháp nối bit.",
  "main_142": "Đáp án A đúng vì phép nối {b, 1} dùng hằng 1 không khai báo độ rộng.\nHằng không định cỡ có thể làm độ rộng nối không như mong muốn hoặc không hợp lệ theo yêu cầu đề.\nNên viết rõ 1'b1 nếu muốn nối thêm đúng 1 bit.",
  "main_143": "Đáp án D đúng vì {4{a}} lặp bit a bốn lần thành 1111.\nSau đó nối b=010 và {2{c}} = 101101.\nGhép theo thứ tự được 1111_010_101101.",
  "main_144": "Đáp án D đúng vì 1 lớn hơn 0 là mệnh đề đúng.\nTrong Verilog, phép so sánh quan hệ trả về 1 nếu đúng và 0 nếu sai.\nKhông có X/Z vì cả hai toán hạng đều xác định.",
  "main_145": "Đáp án C đúng vì biểu thức bên trái chứa bit x nên kết quả so sánh quan hệ không xác định.\nKhi không thể kết luận chắc chắn true/false, Verilog trả về X.\nVì vậy kết quả không phải 0 hay 1.",
  "main_147": "Đáp án B đúng vì: 0, 1, x.\n== là so sánh logic nên nếu gặp X/Z ở vị trí ảnh hưởng kết quả có thể trả về X.\n=== và !== là so sánh case equality, xét cả X và Z như giá trị cụ thể.",
  "main_149": "Đáp án A đúng vì: 0.\n== là so sánh logic nên nếu gặp X/Z ở vị trí ảnh hưởng kết quả có thể trả về X.\n=== và !== là so sánh case equality, xét cả X và Z như giá trị cụ thể.",
  "main_150": "Đáp án C đúng vì: X.\n== là so sánh logic nên nếu gặp X/Z ở vị trí ảnh hưởng kết quả có thể trả về X.\n=== và !== là so sánh case equality, xét cả X và Z như giá trị cụ thể.",
  "main_151": "Đáp án D đúng vì: 1.\n== là so sánh logic nên nếu gặp X/Z ở vị trí ảnh hưởng kết quả có thể trả về X.\n=== và !== là so sánh case equality, xét cả X và Z như giá trị cụ thể.",
  "main_152": "Đáp án A đúng vì: 0.\n== là so sánh logic nên nếu gặp X/Z ở vị trí ảnh hưởng kết quả có thể trả về X.\n=== và !== là so sánh case equality, xét cả X và Z như giá trị cụ thể.",
  "main_153": "Đáp án B đúng vì toán tử điều kiện có dạng cond_expr ? true_expr : false_expr.\nNếu điều kiện đúng thì lấy true_expr, nếu sai thì lấy false_expr.\nĐây là cú pháp thường dùng để mô tả MUX trong mạch tổ hợp.",
  "main_154": "Đáp án A đúng vì biểu thức điều kiện chọn A khi sel=1 và chọn B khi sel=0.\nĐó chính là hành vi của mạch đa hợp MUX 2 sang 1.\nDEMUX là tách một ngõ vào ra nhiều ngõ ra, còn latch/FF là phần tử nhớ.",
  "main_157": "Đáp án D đúng vì -4'd12 là số âm được biểu diễn trong độ rộng 4 bit rồi gán sang regA 16 bit.\nGiá trị -12 trong 16 bit bù 2 tương ứng 65536 - 12 = 65524.\nDo đó regA lưu dạng nhị phân của số 65524.",
  "main_158": "Đáp án B đúng theo bảng ưu tiên trong đề vì các toán tử unary như +, -, !, ~ có mức ưu tiên cao.\nChúng được thực hiện trước các phép toán hai toán hạng như nhân, chia, cộng, trừ.\nVì vậy nhóm + - ! ~ ở đây là nhóm ưu tiên cao nhất.",
  "main_161": "Đáp án D đúng vì câu lệnh assign trong Verilog là phép gán liên tục.\nBiểu thức bên phải được theo dõi liên tục; khi tín hiệu đầu vào thay đổi thì vế trái tự cập nhật.\nCác câu lệnh assign hoạt động song song với nhau, không thực hiện tuần tự như lệnh trong always/initial.\nVì vậy assign có tính liên tục, không theo thứ tự và được thực hiện song song.",
  "main_162": "Đáp án A đúng vì procedural block trong Verilog thực hiện các câu lệnh theo trình tự.\nCác lệnh trong initial/always chạy tuần tự bên trong block, dù các block khác nhau có thể chạy song song.\nDo đó quy trình ở đây được hiểu là chuỗi lệnh thực hiện tuần tự.",
  "main_163": "Đáp án B đúng vì: Bắt đầu tại thời điểm mô phỏng và kết thúc tại câu lệnh cuối cùng trong nó.\ninitial là khối thủ tục chạy một lần khi mô phỏng bắt đầu.\nNó thường dùng trong testbench để khởi tạo tín hiệu, tạo kích thích hoặc kết thúc mô phỏng.",
  "main_165": "Đáp án A đúng vì: Reg.\nKhối always là procedural block; các lệnh bên trong chạy theo sự kiện trong sensitivity list.\nCách chọn sự kiện quyết định mạch là tổ hợp, FF cạnh lên/cạnh xuống hay reset bất đồng bộ.",
  "main_167": "Đáp án A đúng vì: Bất kì sự thay đổi nào từ A, B hoặc sel.\nKhối always là procedural block; các lệnh bên trong chạy theo sự kiện trong sensitivity list.\nCách chọn sự kiện quyết định mạch là tổ hợp, FF cạnh lên/cạnh xuống hay reset bất đồng bộ.",
  "main_168": "Đáp án B đúng vì: Khi có sự thay đổi cạnh lên của xung clk.\nposedge clk biểu diễn sự kiện cạnh lên của clock.\nKhối always dùng sự kiện này thường mô tả Flip-Flop hoặc mạch tuần tự đồng bộ.",
  "main_169": "Đáp án B đúng vì: Khi tín hiệu ctrl lên mức 1.\nKhối always là procedural block; các lệnh bên trong chạy theo sự kiện trong sensitivity list.\nCách chọn sự kiện quyết định mạch là tổ hợp, FF cạnh lên/cạnh xuống hay reset bất đồng bộ.",
  "main_173": "Đáp án B đúng vì $monitor tự động in lại mỗi khi một đối số trong danh sách thay đổi.\nNó tạo các dòng/chuỗi quan sát rời rạc theo thời điểm thay đổi trong mô phỏng.\nKhác với $display, $monitor tiếp tục theo dõi sau khi được gọi.",
  "main_174": "Đáp án A đúng vì định dạng %o dùng để in giá trị ở hệ bát phân.\nTrong $display hoặc $monitor, mỗi mã định dạng quy định cách hiển thị dữ liệu.\nVí dụ %b là nhị phân, %d là thập phân, %h là thập lục phân.",
  "main_175": "Đáp án C đúng vì %f dùng để in số thực dạng dấu phẩy động ở hệ thập phân.\nNó thường áp dụng cho kiểu real hoặc giá trị thực trong mô phỏng.\nKhông dùng %f để in nhị phân, bát phân hay thập lục phân.",
  "main_177": "Đáp án B đúng vì các ngôn ngữ truyền thống như C, Fortran, Java là ngôn ngữ lập trình tuần tự.\nChúng được dùng để viết phần mềm, không mô tả trực tiếp cấu trúc phần cứng song song như HDL.\nVerilog/VHDL mới là ngôn ngữ mô tả phần cứng chuyên dụng.",
  "main_178": "Đáp án C đúng vì ngôn ngữ truyền thống thực thi theo luồng lệnh tuần tự.\nMạch số thực tế hoạt động song song, nhiều khối logic cập nhật đồng thời.\nVì vậy cần HDL để mô tả tính song song và cấu trúc phần cứng.",
  "main_180": "Đáp án A đúng vì: Hai phần chính là khai báo entity và architecture.\nMột thiết kế VHDL cơ bản gồm entity và architecture.\nEntity khai báo giao tiếp vào/ra, còn architecture mô tả hoạt động/cấu trúc bên trong.",
  "main_181": "Đáp án B đúng vì: Chứa các hoạt động bên trong hoặc tổ chức của mạch điện.\nArchitecture mô tả phần bên trong của mạch: hành vi, cấu trúc hoặc các liên kết logic.\nEntity chỉ khai báo giao tiếp ngoài của mạch.",
  "main_182": "Đáp án C đúng vì trong mạch số, khi một tín hiệu thay đổi thì chỉ các khối/logic phụ thuộc vào tín hiệu đó được kích hoạt.\nCác phần mạch không liên quan không cần thay đổi.\nĐây là cách mô phỏng theo sự kiện trong HDL.",
  "main_183": "Đáp án B đúng theo phạm vi đề vì số nhị phân có parity chẵn khi tổng số bit 1 là chẵn.\nĐây là khái niệm chẵn/lẻ theo số lượng bit 1, không phải giá trị số chia hết cho 2.\nCần phân biệt với số nguyên chẵn trong hệ nhị phân thường có bit LSB bằng 0.",
  "main_185": "Đáp án A đúng vì: Các lệnh đồng thời.\nArchitecture mô tả phần bên trong của mạch: hành vi, cấu trúc hoặc các liên kết logic.\nEntity chỉ khai báo giao tiếp ngoài của mạch.",
  "main_187": "Đáp án B đúng vì: Ít nhất một ngõ vào bằng 1.\nCổng OR cho ngõ ra bằng 1 khi có ít nhất một ngõ vào bằng 1.\nChỉ khi tất cả ngõ vào bằng 0 thì OR mới cho ra 0.",
  "main_189": "Đáp án A đúng vì: Để tạo ra một mạch từ một đặc điểm kỹ thuật nhất định.\nSynthesis là quá trình chuyển đặc tả/mô tả HDL thành cấu trúc mạch phần cứng.\nNó khác với mô phỏng, vì mô phỏng chỉ kiểm tra hành vi còn tổng hợp tạo netlist logic.",
  "main_190": "Đáp án C đúng vì: Z.\nNet không có nguồn điều khiển sẽ ở trạng thái trở kháng cao Z.\nZ biểu thị đường dây bị thả nổi, không bị kéo lên 1 hoặc kéo xuống 0.",
  "main_191": "Đáp án D đúng vì Verilog chuẩn hỗ trợ 4 giá trị logic chính: 0, 1, X và Z.\nU là trạng thái thường gặp trong VHDL/std_logic, không phải mức logic chuẩn của Verilog.\nVì vậy U là mức không được hỗ trợ trong câu hỏi này.",
  "main_193": "Đáp án C đúng vì: Cả A và D.\nFPGA có chi phí phát triển ban đầu thấp và có thể cấu hình lại nên linh hoạt hơn ASIC.\nTuy nhiên FPGA thường không nhanh và tối ưu bằng ASIC khi sản xuất số lượng lớn.",
  "main_194": "Đáp án C đúng vì trạng thái tri-state nghĩa là ngõ ra được cách ly điện khỏi đường bus.\nKhi đó ngõ ra ở trạng thái Z, không kéo bus lên 1 hay xuống 0.\nNó không phải mức điện áp nằm giữa 0 và 1.",
  "main_196": "Đáp án C đúng theo phạm vi đề vì phép cộng có bit X ở toán hạng làm lan truyền trạng thái không xác định.\nKhi carry và các bit kết quả bị ảnh hưởng bởi X, kết quả có thể trở thành xxxx.\nCần kiểm tra lại đáp án vì một số phép tính bit có thể xác định được một phần tùy công cụ/mô hình.",
  "main_197": "Đáp án C đúng vì kết quả là 6'b111000.\nA = 8'b00111001, đánh số bit từ A[7] đến A[0] nên A[5:3] = 111.\nB = ~|A là phép NOR rút gọn: vì A có ít nhất một bit 1 nên |A = 1, do đó B = 0.\n{3{B}} nghĩa là lặp B 3 lần, nên được 000.\nVậy {A[5:3], {3{B}}} = {111, 000} = 6'b111000.",
  "main_198": "Đáp án A đúng vì số không dấu 8 bit có dải từ 0 đến 2^8 - 1.\n2^8 = 256 giá trị khác nhau, nên giá trị lớn nhất là 255.\nSố 256 cần 9 bit để biểu diễn.",
  "main_199": "Đáp án A đúng vì FPGA cho phép nạp lại cấu hình nhanh mà không cần chế tạo chip riêng.\nNhờ không phải tapeout/mask như ASIC, vòng lặp thiết kế - kiểm thử ngắn hơn.\nFull custom và standard cell thường mất thời gian chế tạo/kiểm chứng lâu hơn.",
  "main_200": "Đáp án D đúng vì: Số thập lục phân 32 bit.\nHằng hex không ghi độ rộng được xem là hằng không định cỡ.\nTheo phạm vi đề, hằng không định cỡ thường được lấy theo độ rộng mặc định 32 bit.",
  "main_202": "Đáp án C đúng vì số bù 2 8 bit có dải từ -2^7 đến 2^7 - 1.\nDo đó dải là -128 đến +127.\nSố âm nhỏ nhất biểu diễn được là -128.",
  "main_203": "Đáp án B đúng vì delay trong initial là delay tương đối.\nSau #5, câu lệnh 1 chạy ở thời điểm 5; sau đó #15 nữa, câu lệnh 2 chạy ở thời điểm 20.\nVì vậy không phải thời điểm 15 tính từ đầu mô phỏng.",
  "main_205": "Đáp án B đúng vì ^A là reduction XOR của A=10011, có 3 bit 1 nên C=1.\nA[3:1] = 001, {2{C}} = 11 và B[2:0] = 110.\nGhép lại được 00111110.",
  "main_207": "Đáp án C đúng vì: Cần thiết.\nMạch tổ hợp thuần phải nhạy với mọi tín hiệu đầu vào ảnh hưởng đến ngõ ra.\nNếu thiếu input trong sensitivity list, mô phỏng có thể không cập nhật đúng và dễ suy ra latch ngoài ý muốn.",
  "main_210": "Đáp án A đúng vì: Nó được sử dụng để chỉ định một khối thủ tục chỉ được thực hiện một lần.\ninitial là khối thủ tục chạy một lần khi mô phỏng bắt đầu.\nNó thường dùng trong testbench để khởi tạo tín hiệu, tạo kích thích hoặc kết thúc mô phỏng.",
  "main_211": "Đáp án C đúng vì: always @(posedge clk or negedge clear).\nposedge clk biểu diễn sự kiện cạnh lên của clock.\nKhối always dùng sự kiện này thường mô tả Flip-Flop hoặc mạch tuần tự đồng bộ.",
  "main_212": "Đáp án D đúng vì theo đề chỉ A và C đúng.\nassign là phép gán liên tục, chủ yếu tạo logic tổ hợp nhưng có thể mô hình hóa hồi tiếp/latch trong một số trường hợp.\nChỉ số biến ở RHS thường tạo MUX, còn ghi chọn ở LHS có thể tạo decoder/logic chọn ghi.\nB sai vì toán tử điều kiện không phải lúc nào cũng bắt buộc tạo MUX vật lý riêng.",
  "main_215": "Đáp án B đúng vì các câu được phép là A và D.\nA: B[3:0] = D[4:1] + 1; hợp lệ vì B là biến kiểu reg, nên có thể được gán trong khối procedural như always/initial. Dù D là wire, nó vẫn có thể được đọc ở vế phải.\nD: C = A + D; hợp lệ vì C là integer, cũng là kiểu biến có thể nhận gán trong procedural block.\nC sai vì D là wire, mà wire không được gán trực tiếp bằng lệnh procedural như D = A + B;.\nMuốn gán cho wire phải dùng assign hoặc nối từ output của module/cổng.",
  "main_217": "Đáp án D đúng vì A và C đều đúng theo phạm vi đề.\nA đúng vì câu lệnh assign là phép gán liên tục, dùng để gán biểu thức ở vế phải cho tín hiệu net/wire ở vế trái.\nB sai vì trong Verilog truyền thống, assign không dùng để gán trực tiếp cho biến kiểu reg; reg thường được gán trong always hoặc initial.\nC đúng vì assign/dataflow có thể dùng để mô tả phần logic tổ hợp trong các thiết kế như mạch chốt hoặc mạch tuần tự.",
  "main_218": "Đáp án C đúng vì: Tất cả đều sai.\nrepeat(n) lặp một khối lệnh đúng n lần, với n là biểu thức số lần lặp.\nNó không phải vòng lặp vô hạn và cũng không lặp đến khi điều kiện đúng như while.",
  "main_219": "Đáp án B đúng theo tính toán tuần tự trong initial block.\nSau a=b+c thì a=17; sau b=a-15 thì b=2.\nSau c=a+d thì c=34; cuối cùng d=c+d=34+17=51.\nCần kiểm tra lại đáp án vì đáp án B trong lựa chọn là 51 nếu dữ liệu gốc sắp xếp như đề.",
  "main_220": "Đáp án A đúng vì: Nó chỉ định độ trễ 5 đơn vị thời gian trước khi thực hiện câu lệnh tiếp theo.\n#5 là delay 5 đơn vị thời gian trước khi thực hiện câu lệnh kế tiếp.\nĐây là thời gian trễ tương đối trong mô phỏng, không nhất thiết luôn là 5 ns.",
  "main_221": "Đáp án D đúng vì: Tất cả các biến sẽ nhận được giá trị được lưu trữ trước đó trong \"x\".\nposedge clk biểu diễn sự kiện cạnh lên của clock.\nKhối always dùng sự kiện này thường mô tả Flip-Flop hoặc mạch tuần tự đồng bộ.",
  "main_223": "Đáp án D đúng theo dữ liệu đề vì các lệnh <= trong cùng always cập nhật không chặn, nên dùng giá trị cũ ở vế phải.\nĐoạn code có hồi tiếp giữa a và b nên hành vi phụ thuộc trạng thái trước đó.\nCâu này cần dựa vào đầy đủ lựa chọn/giá trị ban đầu để kết luận chắc chắn.\nCần kiểm tra lại đáp án.",
  "main_225": "Đáp án C đúng vì hai phép gán NOR có hồi tiếp chéo tạo phần tử nhớ 1 bit.\nCấu trúc này tương đương một latch SR dùng cổng NOR.\nKhông phải mạch tổ hợp thuần vì ngõ ra quay lại ảnh hưởng ngõ vào logic.",
  "main_226": "Đáp án B và D là các phát biểu sai về module Verilog.\nMỗi lần khởi tạo module sẽ tạo một phần cứng tương ứng sau tổng hợp, không dùng chung một bản sao duy nhất.\nVerilog cũng cho phép khởi tạo nhiều instance của cùng một module.",
  "main_227": "Đáp án C đúng vì câu lệnh forever không có delay nên lặp vô hạn ngay tại thời điểm mô phỏng hiện tại.\nCác câu lệnh repeat và #75 $finish phía sau không có cơ hội thực thi.\nVì vậy khối initial không bao giờ kết thúc.",
  "main_229": "Đáp án C đúng theo phạm vi đề vì Verilog được dùng phổ biến trong công nghiệp thiết kế số tại Mỹ.\nVerilog có cú pháp gần C nên dễ tiếp cận với nhiều kỹ sư phần cứng.\nVHDL thường được nhắc là phổ biến hơn ở châu Âu trong các tài liệu cơ bản.",
  "main_230": "Đáp án A đúng vì VHDL thường được xem là phổ biến hơn ở châu Âu trong các tài liệu nhập môn.\nVHDL có cú pháp chặt chẽ, phù hợp môi trường yêu cầu mô tả rõ kiểu dữ liệu.\nVerilog thường được nêu là phổ biến hơn tại Mỹ.",
  "main_231": "Đáp án A đúng vì trong phạm vi đề, VHDL được xem là ngôn ngữ mô tả phần cứng linh hoạt hơn.\nVHDL có hệ kiểu dữ liệu mạnh, cấu trúc mô tả chặt chẽ và hỗ trợ nhiều mức trừu tượng như entity, architecture, package, component và generic.\nNhờ đó VHDL phù hợp với các thiết kế lớn, cần mô tả rõ ràng và dễ tái sử dụng.\nVerilog thường ngắn gọn, dễ viết hơn, nhưng VHDL linh hoạt hơn về cấu trúc và kiểu dữ liệu.\nC và C++ không phải ngôn ngữ mô tả phần cứng chuyên dụng như VHDL hoặc Verilog.",
  "main_232": "Đáp án C đúng theo phạm vi đề vì Verilog hỗ trợ mô tả mức cổng/switch và gần với biểu diễn phần cứng mức thấp.\nCác primitive và mô hình transistor/switch giúp mô tả gần cấp bóng bán dẫn hơn.\nVHDL thường mạnh ở mô tả kiểu dữ liệu và mức hệ thống.",
  "main_233": "Đáp án C đúng vì đoạn code có lỗi ở phần định danh/tên tín hiệu.\nHeader module thiếu tên module, và biểu thức dùng cin trong khi cổng khai báo là ci.\nĐây là lỗi làm chương trình không biên dịch đúng.\nCần kiểm tra lại đáp án nếu lựa chọn gốc phân loại lỗi khác.",
  "main_234": "Đáp án A đúng vì chương trình ghép nhiều FullAdder để cộng hai bus 4 bit.\nCác tín hiệu c1, c2, c3 truyền carry từ bit thấp lên bit cao.\nNgõ ra R rộng 5 bit để chứa tổng 4 bit kèm carry cuối.",
  "main_235": "Đáp án C đúng vì assign Y = A & B mô tả trực tiếp cổng AND hai ngõ vào.\nY chỉ bằng 1 khi cả A và B đều bằng 1.\nĐây là mạch tổ hợp đơn giản, không có phần tử nhớ.",
  "main_237": "Đáp án B đúng vì code dùng input 2 bit để kích một trong bốn bit ngõ ra.\nVới I lần lượt 00, 01, 10, 11 thì O lần lượt là 0001, 0010, 0100, 1000.\nĐó là mạch giải mã 2 sang 4.",
  "main_238": "Đáp án C đúng theo dữ liệu đề cho trường hợp EN=1, HL=0 và I=2'b10.\nEN cho phép mạch hoạt động, I=10 chọn một nhánh trong bộ giải mã/điều khiển.\nDo thiếu đầy đủ đoạn code trong câu hỏi rút gọn, nên cần đối chiếu lại bảng gán temp của đề gốc.\nCần kiểm tra lại đáp án.",
  "main_240": "Đáp án C đúng vì khi EN=0, chương trình đi vào nhánh if đầu tiên.\nKhi đó temp được gán bằng 4'b0000, không phụ thuộc vào giá trị của I.\nDòng assign O = (HL == 1'b1) ? temp : ~temp; chọn temp khi HL=1.\nVì HL=1 nên O = temp = 4'b0000.\nDo đó ngõ ra là 0000.",
  "main_241": "Đáp án A đúng vì code chọn một bit trong I tùy theo sel.\nNếu sel=00 chọn I[0], sel=01 chọn I[1], sel=10 chọn I[2], còn lại chọn I[3].\nĐây là hành vi của mạch MUX 4 sang 1.",
  "main_244": "Đáp án B đúng vì module tạo bộ cộng toàn phần 1 bit.\nS = A ^ B ^ CI là bit tổng, còn CO là carry theo biểu thức đa số của A, B, CI.\nĐây là cấu trúc chuẩn của Full Adder.",
  "main_245": "Đáp án A đúng vì dòng (1) có lỗi định danh module.\nTên module F_(ADDER) chứa dấu ngoặc, không phải định danh Verilog hợp lệ.\nTên module nên viết dạng F_ADDER hoặc một định danh hợp lệ khác.",
  "main_247": "Đáp án A đúng vì dòng 6 viết endmodule; có dấu chấm phẩy ở cuối.\nTrong Verilog, từ khóa kết thúc module phải viết là endmodule, không thêm dấu ;.\nDòng 7 khai báo module mới là hợp lệ, dòng 8 khai báo input wire hợp lệ, dòng 11 khai báo wire cũng hợp lệ.\nVì vậy lỗi nằm ở dòng 6.",
  "main_248": "Đáp án B đúng vì dòng 9 khai báo input [3:-1] B; có chỉ số bit âm -1.\nTrong phạm vi bài học, bus/vector thường phải khai báo bằng chỉ số không âm, ví dụ [3:0].\nNếu B là bus 4 bit giống A thì nên sửa thành input [3:0] B;.\nDòng 8 khai báo input wire [3:0] A hợp lệ, dòng 11 khai báo wire hợp lệ, dòng 12 là gọi module và nối cổng hợp lệ.",
  "main_249": "Đáp án A đúng vì lỗi nằm ở dòng 10: output reg [4:0] S;.\nTrong module ADDER_4B, các bit của S được nối với ngõ ra của các module con F_ADDER, ví dụ .s(S[0]), .s(S[1]), .co(S[4]).\nCác tín hiệu được module con điều khiển qua kết nối cổng nên nên khai báo dạng net/wire, ví dụ output [4:0] S; hoặc output wire [4:0] S;.\nDòng 11 khai báo wire c1, c2, c3; hợp lệ, dòng 12 và 13 là các lệnh khởi tạo module/nối cổng hợp lệ trong phạm vi lựa chọn.",
  "main_250": "Đáp án D đúng vì dòng 15 là dòng có lỗi trong các lựa chọn 12, 13, 14, 15.\nỞ dòng 15, tên instance được đặt là ADDER_4B, trùng với tên module ADDER_4B đang được định nghĩa ở dòng 7.\nTrong phạm vi đề, đây được xem là lỗi tên định danh/ngữ nghĩa vì gây nhầm lẫn giữa tên module và tên instance.\nNên sửa thành một tên instance khác, ví dụ: F_ADDER fad3(...);",
  "main_252": "Đáp án A đúng vì dòng 10 khai báo output reg [4:0] S nhưng S còn được điều khiển bởi các module con qua cổng output.\nTín hiệu nhận từ instance/continuous connection nên nên là wire, không phải reg.\nVì vậy lỗi chính là kiểu biến.",
  "main_253": "Đáp án D đúng vì dòng 16 dùng Endmodule thay vì từ khóa chuẩn endmodule.\nVerilog phân biệt chữ hoa và chữ thường nên Endmodule không được nhận là từ khóa hợp lệ.\nVì vậy lỗi thuộc nhóm từ khóa.",
  "main_254": "Đáp án C đúng vì dòng 15 đặt tên instance là ADDER_4B trùng với tên module đang định nghĩa.\nViệc dùng tên gây nhầm lẫn/không hợp lệ theo quy ước định danh trong đề.\nNên đặt tên instance khác, ví dụ fad3.",
  "main_256": "Đáp án D đúng vì: Cả A, B và C.\nD Flip-Flop lấy mẫu D tại cạnh tác động của clock và lưu vào Q.\nMô tả đúng cần dùng always @(posedge clk) với Q là reg/logic.",
  "main_258": "Đáp án C đúng vì khi khởi tạo module có hai cách nối cổng phổ biến.\nNối theo tên dùng .port(signal), không phụ thuộc thứ tự cổng.\nNối theo vị trí dùng danh sách tín hiệu theo đúng thứ tự khai báo trong module.\nVì cả A và B đều đúng nên chọn C.",
  "main_259": "Đáp án B đúng theo dữ liệu đề: sơ đồ là mạch chốt SR.\nMạch chốt SR có hai tín hiệu Set/Reset và có khả năng lưu trạng thái.\nVì câu này phụ thuộc hình ảnh sơ đồ gốc nên cần đối chiếu lại hình.\nCần kiểm tra lại đáp án.",
  "main_260": "Đáp án B đúng vì đoạn chương trình mô tả một mạch chốt SR có tín hiệu cho phép CLK.\nKhi CLK = 1, nếu R = 1 và S = 0 thì Q = 0, Qb = 1, tức mạch reset.\nKhi CLK = 1, nếu S = 1 và R = 0 thì Q = 1, Qb = 0, tức mạch set.\nKhi CLK không kích hoạt hoặc không rơi vào hai trường hợp trên, mạch giữ nguyên trạng thái trước đó.\nVì ngõ ra phụ thuộc vào S, R và có khả năng lưu trạng thái nên đây là mạch chốt SR, không phải Flip-Flop SR hay mạch D.",
  "main_261": "Đáp án A đúng vì sơ đồ là mạch chốt D.\nTín hiệu D được đưa trực tiếp tạo nhánh S và đi qua cổng NOT để tạo nhánh R, nên S và R luôn bổ sung nhau.\nHai cổng NAND hồi tiếp chéo bên phải có nhiệm vụ lưu trạng thái ngõ ra Q và Q̅.\nKhi tín hiệu cho phép/clock ở mức tác động, Q nhận theo D; khi không cho phép, mạch giữ giá trị cũ.\nKhông chọn chốt SR vì S và R không độc lập; không chọn Flip-Flop vì mạch chốt D nhạy theo mức, không kích theo cạnh.",
  "main_262": "Đáp án A đúng vì chương trình mô tả mạch chốt D.\nKhi clk = 1, câu lệnh q = D; được thực hiện nên q nhận giá trị của D.\nKhi clk = 0, không có lệnh gán mới cho q nên q giữ lại giá trị trước đó.\nKhối always @(clk, D) nhạy theo mức thay đổi của clk và D, không phải theo cạnh clock, nên đây là latch D chứ không phải Flip-Flop.\nCác đáp án SR/JK sai vì mạch không có các ngõ S, R, J, K.",
  "main_264": "Đáp án D đúng vì: Flip Flop T.\nTín hiệu được gán trong always/initial phải là reg trong Verilog truyền thống.\nreg là biến lưu giá trị mô phỏng và có thể tổng hợp thành FF, latch hoặc logic tùy cách mô tả.",
  "main_265": "Đáp án A đúng vì: Thanh ghi dịch 4 bit vào nối tiếp ra nối tiếp.\nwire/net biểu diễn đường nối phần cứng và thường nhận giá trị từ assign, cổng hoặc module.\nNó không được gán trực tiếp trong procedural block như reg.",
  "main_268": "Đáp án A đúng vì mỗi khối TFF là một Flip-Flop T với T = 1 nên ở mỗi cạnh kích hoạt clock, đầu ra sẽ đảo trạng thái.\nBa TFF được mắc nối tiếp kiểu ripple: FF đầu nhận clock ngoài clk, FF thứ hai nhận clock từ qb1, FF thứ ba nhận clock từ qb2.\nVì các tầng sau không dùng cùng một clock chung mà lấy clock từ đầu ra tầng trước nên đây là mạch đếm không đồng bộ.\nCách mắc qua các ngõ QB làm các bit đổi trạng thái theo thứ tự tạo thành bộ đếm lên 3 bit.",
  "main_269": "Đáp án A đúng theo dữ liệu đề: sơ đồ là Flip-Flop T.\nFlip-Flop T giữ trạng thái khi T=0 và đảo trạng thái khi T=1 tại cạnh clock.\nVì câu này phụ thuộc hình ảnh sơ đồ gốc nên cần đối chiếu lại hình.\nCần kiểm tra lại đáp án.",
  "main_271": "Đáp án A đúng vì chương trình làm LED sáng dịch từ ngoài vào trong.\nKhi rst=1, led được gán 8'b1000_0001.\nKhi led dịch hết về 0000_0000, chương trình gán lại led = 8'b1000_0001, tức hai LED ngoài cùng sáng.\nSau mỗi cạnh lên clock, led[3:0] << 1 làm nửa phải dịch vào giữa, còn led[7:4] >> 1 làm nửa trái dịch vào giữa.\nChuỗi điển hình: 1000_0001 → 0100_0010 → 0010_0100 → 0001_1000.",
  "main_273": "Đáp án A đúng vì chương trình làm LED sáng dần từ ngoài vào trong.\nKhi led = 8'b1111_1111, chương trình đưa led về 8'b0000_0000 để bắt đầu lại chu kỳ.\nỞ nhánh else, nhóm led[3:0] được dịch trái rồi cộng thêm 4'b0001, làm các LED phía phải sáng dần.\nNhóm led[7:4] được dịch phải rồi cộng thêm 4'b1000, làm các LED phía trái sáng dần.\nVì hai phía cùng sáng dần tiến vào giữa nên chọn A.",
  "main_274": "Đáp án D đúng vì: Đầu ra phụ thuộc vào trạng thái quá khứ của mạch, cũng như giá trị hiện tại của đầu vào.\nMạch tuần tự có phần tử nhớ nên ngõ ra phụ thuộc cả trạng thái trước đó và đầu vào hiện tại.\nVới mạch đồng bộ, trạng thái thường cập nhật theo cạnh clock.",
  "main_275": "Đáp án A đúng vì: Xung clock.\nMạch tuần tự có phần tử nhớ nên ngõ ra phụ thuộc cả trạng thái trước đó và đầu vào hiện tại.\nVới mạch đồng bộ, trạng thái thường cập nhật theo cạnh clock.",
  "main_276": "Đáp án D đúng vì: Cả A, B và C.\nMạch tuần tự có phần tử nhớ nên ngõ ra phụ thuộc cả trạng thái trước đó và đầu vào hiện tại.\nVới mạch đồng bộ, trạng thái thường cập nhật theo cạnh clock.",
  "main_277": "Đáp án B đúng vì: =.\nBlocking assignment dùng dấu = và thực hiện tuần tự, lệnh sau chờ lệnh trước cập nhật xong.\nNon-blocking assignment dùng <= và cập nhật đồng thời ở cuối bước thời gian, thường dùng cho mạch tuần tự.",
  "main_278": "Đáp án D đúng vì <= là toán tử gán không chặn trong Verilog.\nBlocking assignment dùng dấu = và thực hiện tuần tự, lệnh sau chờ lệnh trước cập nhật xong.\nNon-blocking assignment dùng <= và cập nhật đồng thời ở cuối bước thời gian, thường dùng cho mạch tuần tự.\nVì vậy phép gán không chặn là <=.",
  "main_281": "Đáp án A đúng vì các lệnh dùng blocking assignment = nên được thực hiện tuần tự.\nBan đầu a = b = 0 làm cả a và b bằng 0.\nSau đó a = 1 làm a đổi thành 1 ngay lập tức.\nCuối cùng b = a nên b nhận giá trị hiện tại của a, tức là 1.\nVì vậy kết quả cuối cùng là a = b = 1.",
  "main_282": "Đáp án C đúng vì phép gán không chặn <= lấy mẫu vế phải trước rồi cập nhật sau.\nBan đầu a=b=0; lệnh a<=1 đặt lịch cho a thành 1.\nLệnh b<=a vẫn đọc a cũ bằng 0, nên cuối bước thời gian a=1, b=0.",
  "main_283": "Đáp án A đúng vì: Blocking.\nMạch tích hợp có ưu điểm diện tích nhỏ, tốc độ cao, độ tin cậy tốt và tiêu thụ công suất thấp hơn mạch rời rạc.\nDo nhiều phần tử được tích hợp trên cùng chip nên giảm dây nối và ký sinh.",
  "main_289": "Đáp án A đúng vì: Finite State Machine.\nFSM là viết tắt của Finite State Machine, tức máy trạng thái hữu hạn.\nNó mô tả hệ thống có số trạng thái xác định và chuyển trạng thái theo input/clock.",
  "main_290": "Đáp án A đúng vì: 2.\nMáy trạng thái hữu hạn thường chia thành hai loại chính: Moore và Mealy.\nMoore có output phụ thuộc trạng thái, còn Mealy phụ thuộc cả trạng thái và input.",
  "main_291": "Đáp án C đúng vì: Cả A và B.\nMáy trạng thái hữu hạn thường chia thành hai loại chính: Moore và Mealy.\nMoore có output phụ thuộc trạng thái, còn Mealy phụ thuộc cả trạng thái và input.",
  "main_293": "Đáp án B đúng vì: Đầu ra luôn phụ thuộc vào trạng thái hiện tại, không nhất thiết phụ thuộc vào đầu vào chính.\nĐịnh luật Moore thường phát biểu rằng mật độ/số transistor trên chip tăng rất nhanh theo thời gian, thường xấp xỉ gấp đôi sau khoảng 18-24 tháng.\nTrong phạm vi đề, phương án được chọn mô tả đúng xu hướng tăng mật độ tích hợp.",
  "main_296": "Đáp án C đúng vì: 12.500.000.\nMuốn tạo xung 2 Hz từ clock 50 MHz và đảo ngõ ra mỗi nửa chu kỳ thì cần đếm 50 MHz/(2*2).\nKết quả là 12.500.000 xung clock cho mỗi lần đảo.",
  "main_297": "Đáp án A đúng vì hệ thống tổng thể instantiate hai module con: CK_DIV và DEM_8BIT.\nModule DEM_8BIT_2SPEED chỉ là module top dùng để kết nối hai khối đó.\nVì vậy sơ đồ khối bên trong hệ thống gồm 2 module chính.",
  "main_299": "Đáp án C đúng vì chương trình 2 và 3 có lỗi theo đoạn code.\nỞ chương trình 2, OUT khai báo output wire nhưng lại được gán trong always nên phải là reg.\nỞ chương trình 3, tên cổng .out không khớp với OUT nếu Verilog phân biệt hoa/thường.\nDo đó hai chương trình này cần sửa.",
  "main_302": "Đáp án B đúng vì module tổng thể có các ngõ vào clk_50M, RESET, ud, ss và SPEED.\nĐó là 5 tín hiệu vào điều khiển toàn hệ thống.\nLED_8out là ngõ ra nên không tính vào số ngõ vào."
};

(function applyAINotesToQuestionBank() {
  const notes = window.AI_NOTES || {};
  (window.QUESTION_BANK || []).forEach(q => {
    if (Object.prototype.hasOwnProperty.call(notes, q.id)) {
      q.aiNote = notes[q.id];
    }
  });
})();
